/// Raven `ThrowSaberToAttacker` — drop the Jedi-Master saber toward the killer.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:258-344`
//
// The `#ifdef _DEBUG` `Com_Printf` diagnostics are release-build no-ops and are
// omitted (§20 dead-surface). `gJMSaberEnt` is the resolved `Option<*mut
// gentity_t>` global (see game_globals.rs).
pub fn ThrowSaberToAttacker(
    ctx: GameContext<'_>,self_: *mut gentity_t, attacker: *mut gentity_t) {
    unsafe {
        let base = (*ctx.world).g_entities.as_ptr();
        let client = (*self_).client as *mut gclient_t;
        let mut ent = &mut (*ctx.world).g_entities[(*client).ps.saberIndex as usize] as *mut gentity_t;
        let mut altVelocity: c_int = 0;

        if ent.is_null() || (*ent).enemy != ent_id_opt(base, self_) {
            // something has gone very wrong (this should never happen)
            // but in case it does.. find the saber manually
            ent = (*ctx.world).globals.gJMSaberEnt.unwrap_or(core::ptr::null_mut());

            if ent.is_null() {
                return;
            }

            (*ent).enemy = ent_id_opt(base, self_);
            (*client).ps.saberIndex = (*ent).s.number;
        }

        trap::SetConfigstring(
            ctx.engine,
            GSetConfigstringArgs::new(CS_CLIENT_JEDIMASTER, CString::new("-1").unwrap()),
        );

        if !attacker.is_null() && !(*attacker).client.is_null() && (*client).ps.saberInFlight != qfalse {
            // someone killed us and we had the saber thrown, so actually move this
            // saber to the saber location
            let flyingsaber = &mut (*ctx.world).g_entities[(*client).ps.saberEntityNum as usize] as *mut gentity_t;

            if !flyingsaber.is_null() && (*flyingsaber).inuse != qfalse {
                (*ent).s.pos.trBase = (*flyingsaber).s.pos.trBase;
                (*ent).s.pos.trDelta = (*flyingsaber).s.pos.trDelta;
                (*ent).s.apos.trBase = (*flyingsaber).s.apos.trBase;
                (*ent).s.apos.trDelta = (*flyingsaber).s.apos.trDelta;

                (*ent).r.currentOrigin = (*flyingsaber).r.currentOrigin;
                (*ent).r.currentAngles = (*flyingsaber).r.currentAngles;
                altVelocity = 1;
            }
        }

        // say he threw it anyway in order to properly remove from dead body
        (*client).ps.saberInFlight = qtrue;

        crate::w_saber::WP_SaberAddG2Model(
            ctx,
            ent,
            (*client).saber[0].model.as_ptr(),
            (*client).saber[0].skin,
        );

        (*ent).s.eFlags &= !EF_NODRAW;
        (*ent).s.modelGhoul2 = 1;
        (*ent).s.eType = ET_MISSILE as c_int;
        (*ent).enemy = None;

        if attacker.is_null() || (*attacker).client.is_null() {
            (*ent).s.pos.trBase = (*ent).s.origin2;
            (*ent).s.origin = (*ent).s.origin2;
            (*ent).r.currentOrigin = (*ent).s.origin2;
            (*ent).pos2[0] = 0.0;
            trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));
            return;
        }

        if altVelocity == 0 {
            (*ent).s.pos.trBase = (*self_).s.pos.trBase;
            (*ent).s.origin = (*self_).s.pos.trBase;
            (*ent).r.currentOrigin = (*self_).s.pos.trBase;

            let mut a: vec3_t = [0.0; 3];
            for k in 0..3 {
                a[k] = (*((*attacker).client as *mut gclient_t)).ps.origin[k] - (*ent).s.pos.trBase[k];
            }

            crate::q_math::VectorNormalize(&mut a);

            (*ent).s.pos.trDelta[0] = a[0] * 256.0;
            (*ent).s.pos.trDelta[1] = a[1] * 256.0;
            (*ent).s.pos.trDelta[2] = 256.0;
        }

        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));
    }
}

/// Raven `JMSaberThink`.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:346-383`
//
// `JMSaberThink` is stored elsewhere as an `EntThink` dispatch target
// (`ent_fn_enums::EntThink::JMSaberThink`); this is its body. `pos2` is a
// `vec3_t`, so the `pos2[0/1]` flag/timer reads/writes are `f32` exactly as C's
// float-slot arithmetic.
pub fn JMSaberThink(
    ctx: GameContext<'_>,ent: *mut gentity_t) {
    unsafe {
        (*ctx.world).globals.gJMSaberEnt = Some(ent);

        if let Some(enemy_id) = (*ent).enemy {
            let enemy = &mut (*ctx.world).g_entities[enemy_id.index()] as *mut gentity_t;
            if (*enemy).client.is_null() || (*enemy).inuse == qfalse {
                // disconnected?
                (*ent).s.pos.trBase = (*enemy).s.pos.trBase;
                (*ent).s.origin = (*enemy).s.pos.trBase;
                (*ent).r.currentOrigin = (*enemy).s.pos.trBase;
                (*ent).s.modelindex = crate::g_utils::G_ModelIndex(
                    b"models/weapons2/saber/saber_w.glm\0".as_ptr() as *const c_char,
                );
                (*ent).s.eFlags &= !EF_NODRAW;
                (*ent).s.modelGhoul2 = 1;
                (*ent).s.eType = ET_MISSILE as c_int;
                (*ent).enemy = None;

                (*ent).pos2[0] = 1.0;
                (*ent).pos2[1] = 0.0; // respawn next think
                trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));
            } else {
                (*ent).pos2[1] = ((*ctx.world).level.time + JMSABER_RESPAWN_TIME) as f32;
            }
        } else if (*ent).pos2[0] != 0.0 && (*ent).pos2[1] < (*ctx.world).level.time as f32 {
            (*ent).s.pos.trBase = (*ent).s.origin2;
            (*ent).s.origin = (*ent).s.origin2;
            (*ent).r.currentOrigin = (*ent).s.origin2;
            (*ent).pos2[0] = 0.0;
            trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));
        }

        (*ent).nextthink = (*ctx.world).level.time + 50;
        crate::g_object::G_RunObject(ctx, ent);
    }
}

/// Raven `JMSaberTouch` — pick up the JM saber, become the Jedi Master.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:385-469`
// PORT-NOTE(traps-va-plus-fn-ptr-store): calls `trap_SetConfigstring`/
// `trap_SendServerCommand` with `va(...)` varargs, `G_KillG2Queue`, reads
// `g_spawnInvulnerability`/`level`; stored as a `touch` fn-pointer (raw
// `extern "C" fn`, not the `EntTouch` enum).
pub fn JMSaberTouch(
    ctx: GameContext<'_>,self_: *mut gentity_t, other: *mut gentity_t, trace: *mut trace_t) {
    unsafe {
        if other.is_null() || (*other).client.is_null() || (*other).health < 1 {
            return;
        }

        if (*self_).enemy.is_some() {
            return;
        }

        if (*self_).s.modelindex == 0 {
            return;
        }

        if (*((*other).client as *mut gclient_t)).ps.stats[STAT_WEAPONS as usize] & (1 << WP_SABER) != 0 {
            return;
        }

        if (*((*other).client as *mut gclient_t)).ps.isJediMaster != 0 {
            return;
        }

        let base = (*ctx.world).g_entities.as_ptr();
        (*self_).enemy = Some(ent_id(base, other));
        (*((*other).client as *mut gclient_t)).ps.stats[STAT_WEAPONS as usize] = 1 << WP_SABER;
        (*((*other).client as *mut gclient_t)).ps.weapon = WP_SABER;
        (*other).s.weapon = WP_SABER;
        G_AddEvent(other, (EV_BECOME_JEDIMASTER) as i32, 0);

        // Track the jedi master
        let cs = format!("{}", (*other).s.number);
        trap::SetConfigstring(
            ctx.engine,
            GSetConfigstringArgs::new(CS_CLIENT_JEDIMASTER, cstr(&cs)),
        );

        if (*ctx.world).cvars.g_spawnInvulnerability.integer != 0 {
            (*((*other).client as *mut gclient_t)).ps.eFlags |= EF_INVULNERABLE;
            (*((*other).client as *mut gclient_t)).invulnerableTimer =
                (*ctx.world).level.time + (*ctx.world).cvars.g_spawnInvulnerability.integer;
        }

        let msg = format!(
            "cp \"{} {}\n\"",
            cstr_to_str((*((*other).client as *mut gclient_t)).pers.netname.as_ptr()),
            cstr_to_str(G_GetStringEdString(ctx, c"MP_SVGAME".as_ptr() as *mut c_char, c"BECOMEJM".as_ptr() as *mut c_char))
        );
        trap::SendServerCommand(ctx.engine, GSendServerCommandArgs::new(-1, cstr(&msg)));

        (*((*other).client as *mut gclient_t)).ps.isJediMaster = qtrue;
        (*((*other).client as *mut gclient_t)).ps.saberIndex = (*self_).s.number;

        if (*other).health < 200 && (*other).health > 0 {
            // full health when you become the Jedi Master
            (*((*other).client as *mut gclient_t)).ps.stats[STAT_HEALTH as usize] = 200;
            (*other).health = 200;
        }

        if (*((*other).client as *mut gclient_t)).ps.fd.forcePower < 100 {
            (*((*other).client as *mut gclient_t)).ps.fd.forcePower = 100;
        }

        let mut i = 0;
        while i < NUM_FORCE_POWERS {
            (*((*other).client as *mut gclient_t)).ps.fd.forcePowersKnown |= 1 << i;
            (*((*other).client as *mut gclient_t)).ps.fd.forcePowerLevel[i as usize] = FORCE_LEVEL_3;
            i += 1;
        }

        (*self_).pos2[0] = 1.0;
        (*self_).pos2[1] = ((*ctx.world).level.time + JMSABER_RESPAWN_TIME) as f32;

        (*self_).s.modelindex = 0;
        (*self_).s.eFlags |= EF_NODRAW;
        (*self_).s.modelGhoul2 = 0;
        (*self_).s.eType = ET_GENERAL as c_int;

        // PORT-NOTE(dead-code): the `te = G_TempEntity(...)` broadcast block is
        // commented out in the oracle (g_client.c:461-465) — dropped per §20.
        crate::g_utils::G_KillG2Queue(ctx, (*self_).s.number);
    }
}

/// Raven `SP_info_jedimaster_start` — the JM saber spawn point.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:476-516`
// PORT-NOTE(fn-ptr-store-shape-mismatch): stores `ent->touch = JMSaberTouch`
// and `ent->think = JMSaberThink` into the still-raw `gentity_t` fn pointers,
// writes `gJMSaberEnt`, reads `g_gametype`/`level`, calls `trap_LinkEntity`.
pub fn SP_info_jedimaster_start(
    ctx: GameContext<'_>,ent: *mut gentity_t) {
    unsafe {
        if (*ctx.world).cvars.g_gametype.integer != GT_JEDIMASTER {
            (*ctx.world).globals.gJMSaberEnt = None;
            crate::g_utils::G_FreeEntity(ctx, ent);
            return;
        }

        (*ent).enemy = None;

        (*ent).flags = FL_BOUNCE_HALF;

        (*ent).s.modelindex =
            G_ModelIndex(b"models/weapons2/saber/saber_w.glm\0".as_ptr() as *const c_char);
        (*ent).s.modelGhoul2 = 1;
        (*ent).s.g2radius = 20;
        // (*ent).s.eType = ET_GENERAL;
        (*ent).s.eType = ET_MISSILE as c_int;
        (*ent).s.weapon = WP_SABER;
        (*ent).s.pos.trType = TR_GRAVITY;
        (*ent).s.pos.trTime = (*ctx.world).level.time;
        crate::q_math::VectorSet(&mut (*ent).r.maxs, 3.0, 3.0, 3.0);
        crate::q_math::VectorSet(&mut (*ent).r.mins, -3.0, -3.0, -3.0);
        (*ent).r.contents = CONTENTS_TRIGGER;
        (*ent).clipmask = MASK_SOLID;

        (*ent).isSaberEntity = qtrue;

        (*ent).bounceCount = -5;

        (*ent).physicsObject = qtrue;

        // remember the spawn spot
        crate::q_math::_VectorCopy((*ent).s.pos.trBase, &mut (*ent).s.origin2);

        (*ent).touch = Some(EntTouch::JMSaberTouch);

        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));

        (*ent).think = Some(EntThink::JMSaberThink);
        (*ent).nextthink = (*ctx.world).level.time + 50;
    }
}

/// Raven `SpotWouldTelefrag` — would a client spawn on `spot` overlap another
/// client?
///
/// Source: `oracle/oracle/codemp/game/g_client.c:532-552`
pub fn SpotWouldTelefrag(ctx: GameContext<'_>, spot: *mut gentity_t) -> qboolean {
    unsafe {
        let mut touch: [c_int; MAX_GENTITIES] = [0; MAX_GENTITIES];
        let mut mins: vec3_t = [0.0; 3];
        let mut maxs: vec3_t = [0.0; 3];

        for k in 0..3 {
            mins[k] = (*spot).s.origin[k] + playerMins[k];
            maxs[k] = (*spot).s.origin[k] + playerMaxs[k];
        }
        let num = trap::EntitiesInBox(
            ctx.engine,
            GEntitiesInBoxArgs::new(
                &mins as *const vec3_t,
                &maxs as *const vec3_t,
                touch.as_mut_ptr(),
                MAX_GENTITIES as c_int,
            ),
        );

        let mut i = 0;
        while i < num {
            let hit = &mut (*ctx.world).g_entities[touch[i as usize] as usize] as *mut gentity_t;
            // if ( hit->client && hit->client->ps.stats[STAT_HEALTH] > 0 ) — the
            // health test is commented out in Raven; any client presence telefrags.
            if !(*hit).client.is_null() {
                return qtrue;
            }
            i += 1;
        }

        qfalse
    }
}

/// Raven `SpotWouldTelefrag2` — would `mover` moved to `dest` overlap a solid?
///
/// Source: `oracle/oracle/codemp/game/g_client.c:554-580`
pub fn SpotWouldTelefrag2(ctx: GameContext<'_>, mover: *mut gentity_t, dest: vec3_t) -> qboolean {
    unsafe {
        let mut touch: [c_int; MAX_GENTITIES] = [0; MAX_GENTITIES];
        let mut mins: vec3_t = [0.0; 3];
        let mut maxs: vec3_t = [0.0; 3];

        for k in 0..3 {
            mins[k] = dest[k] + (*mover).r.mins[k];
            maxs[k] = dest[k] + (*mover).r.maxs[k];
        }
        let num = trap::EntitiesInBox(
            ctx.engine,
            GEntitiesInBoxArgs::new(
                &mins as *const vec3_t,
                &maxs as *const vec3_t,
                touch.as_mut_ptr(),
                MAX_GENTITIES as c_int,
            ),
        );

        let mut i = 0;
        while i < num {
            let hit = &mut (*ctx.world).g_entities[touch[i as usize] as usize] as *mut gentity_t;
            if hit == mover {
                i += 1;
                continue;
            }
            if (*hit).r.contents & (*mover).r.contents != 0 {
                return qtrue;
            }
            i += 1;
        }

        qfalse
    }
}

/// Raven `SelectNearestDeathmatchSpawnPoint` — find the spot we DON'T want.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:590-611`
pub fn SelectNearestDeathmatchSpawnPoint(
    ctx: GameContext<'_>,from: vec3_t) -> *mut gentity_t {
    unsafe {
        let mut nearestDist: f32 = 999999.0;
        let mut nearestSpot: *mut gentity_t = core::ptr::null_mut();
        let mut spot: *mut gentity_t = core::ptr::null_mut();

        loop {
            spot = crate::g_utils::G_Find(ctx, 
                spot,
                fofs_classname(),
                b"info_player_deathmatch\0".as_ptr() as *const c_char,
            );
            if spot.is_null() {
                break;
            }
            let mut delta: vec3_t = [0.0; 3];
            for k in 0..3 {
                delta[k] = (*spot).s.origin[k] - from[k];
            }
            let dist = VectorLength(delta);
            if dist < nearestDist {
                nearestDist = dist;
                nearestSpot = spot;
            }
        }

        nearestSpot
    }
}

/// Raven `SelectRandomDeathmatchSpawnPoint` — a random non-telefragging spot.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:622-645`
pub fn SelectRandomDeathmatchSpawnPoint(ctx: GameContext<'_>) -> *mut gentity_t {
    pub const MAX_SPAWN_POINTS: usize = 128;
    unsafe {
        let mut count: c_int = 0;
        let mut spot: *mut gentity_t = core::ptr::null_mut();
        let mut spots: [*mut gentity_t; MAX_SPAWN_POINTS] = [core::ptr::null_mut(); MAX_SPAWN_POINTS];

        loop {
            spot = crate::g_utils::G_Find(ctx, 
                spot,
                fofs_classname(),
                b"info_player_deathmatch\0".as_ptr() as *const c_char,
            );
            if spot.is_null() {
                break;
            }
            if SpotWouldTelefrag(ctx, spot) != 0 {
                continue;
            }
            spots[count as usize] = spot;
            count += 1;
        }

        if count == 0 {
            // no spots that won't telefrag
            return crate::g_utils::G_Find(ctx, 
                core::ptr::null_mut(),
                fofs_classname(),
                b"info_player_deathmatch\0".as_ptr() as *const c_char,
            );
        }

        let selection = (*ctx.world).bg_state.rng.rand() % count;
        spots[selection as usize]
    }
}

/// Raven `SelectRandomFurthestSpawnPoint` — a start furthest from the avoid
/// point.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:654-758`
//
// fork-9: `origin`/`angles` are written through (out-params) → `&mut [f32;3]`;
// `avoidPoint` is read-only → kept by-value.
pub fn SelectRandomFurthestSpawnPoint(
    ctx: GameContext<'_>,
    avoidPoint: vec3_t,
    origin: &mut [f32; 3],
    angles: &mut [f32; 3],
    team: team_t,
) -> *mut gentity_t {
    unsafe {
        let mut list_dist = [0.0f32; 64];
        let mut list_spot: [*mut gentity_t; 64] = [core::ptr::null_mut(); 64];
        let mut numSpots: c_int = 0;
        let mut spot: *mut gentity_t = core::ptr::null_mut();

        // in Team DM, look for a team start spot first, if any
        if (*ctx.world).cvars.g_gametype.integer == GT_TEAM
            && team != TEAM_FREE
            && team != TEAM_SPECTATOR
        {
            let classname = if team == TEAM_RED {
                b"info_player_start_red\0".as_ptr() as *const c_char
            } else {
                b"info_player_start_blue\0".as_ptr() as *const c_char
            };
            loop {
                spot = crate::g_utils::G_Find(ctx, spot, fofs_classname(), classname);
                if spot.is_null() {
                    break;
                }
                if SpotWouldTelefrag(ctx, spot) != 0 {
                    continue;
                }
                let mut delta: vec3_t = [0.0; 3];
                for k in 0..3 {
                    delta[k] = (*spot).s.origin[k] - avoidPoint[k];
                }
                let dist = VectorLength(delta);
                let mut i = 0;
                while i < numSpots {
                    if dist > list_dist[i as usize] {
                        if numSpots >= 64 {
                            numSpots = 64 - 1;
                        }
                        let mut j = numSpots;
                        while j > i {
                            list_dist[j as usize] = list_dist[(j - 1) as usize];
                            list_spot[j as usize] = list_spot[(j - 1) as usize];
                            j -= 1;
                        }
                        list_dist[i as usize] = dist;
                        list_spot[i as usize] = spot;
                        numSpots += 1;
                        if numSpots > 64 {
                            numSpots = 64;
                        }
                        break;
                    }
                    i += 1;
                }
                if i >= numSpots && numSpots < 64 {
                    list_dist[numSpots as usize] = dist;
                    list_spot[numSpots as usize] = spot;
                    numSpots += 1;
                }
            }
        }

        if numSpots == 0 {
            // couldn't find any of the above
            spot = core::ptr::null_mut();
            loop {
                spot = crate::g_utils::G_Find(ctx, spot, fofs_classname(), b"info_player_deathmatch\0".as_ptr() as *const c_char);
                if spot.is_null() {
                    break;
                }
                if SpotWouldTelefrag(ctx, spot) != 0 {
                    continue;
                }
                let mut delta: vec3_t = [0.0; 3];
                for k in 0..3 {
                    delta[k] = (*spot).s.origin[k] - avoidPoint[k];
                }
                let dist = VectorLength(delta);
                let mut i = 0;
                while i < numSpots {
                    if dist > list_dist[i as usize] {
                        if numSpots >= 64 {
                            numSpots = 64 - 1;
                        }
                        let mut j = numSpots;
                        while j > i {
                            list_dist[j as usize] = list_dist[(j - 1) as usize];
                            list_spot[j as usize] = list_spot[(j - 1) as usize];
                            j -= 1;
                        }
                        list_dist[i as usize] = dist;
                        list_spot[i as usize] = spot;
                        numSpots += 1;
                        if numSpots > 64 {
                            numSpots = 64;
                        }
                        break;
                    }
                    i += 1;
                }
                if i >= numSpots && numSpots < 64 {
                    list_dist[numSpots as usize] = dist;
                    list_spot[numSpots as usize] = spot;
                    numSpots += 1;
                }
            }
            if numSpots == 0 {
                spot = crate::g_utils::G_Find(ctx, core::ptr::null_mut(), fofs_classname(), b"info_player_deathmatch\0".as_ptr() as *const c_char);
                if spot.is_null() {
                    // Raven `G_Error("Couldn't find a spawn point")` drops the game
                    // (frozen Group A: `Com_Error`/`G_Error` → panic).
                    panic!("Couldn't find a spawn point");
                }
                *origin = (*spot).s.origin;
                origin[2] += 9.0;
                *angles = (*spot).s.angles;
                return spot;
            }
        }

        // select a random spot from the spawn points furthest away
        let rnd = ((*ctx.world).bg_state.rng.random() * ((numSpots / 2) as f32)) as c_int;

        *origin = (*list_spot[rnd as usize]).s.origin;
        origin[2] += 9.0;
        *angles = (*list_spot[rnd as usize]).s.angles;

        list_spot[rnd as usize]
    }
}

