/// Raven `InitBodyQue` — allocate the body-queue entities.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:953-964`
pub fn InitBodyQue(ctx: GameContext<'_>) {
    unsafe {
        (*ctx.world).level.bodyQueIndex = 0;
        for i in 0..BODY_QUEUE_SIZE {
            let ent = crate::g_utils::G_Spawn(ctx);
            (*ent).classname = b"bodyque\0".as_ptr() as *mut c_char;
            (*ent).neverFree = qtrue;
            (*ctx.world).level.bodyQue[i] = ent;
        }
    }
}

/// Raven `BodySink` — after death, sink the body into the ground and remove.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:973-986`
pub fn BodySink(
    ctx: GameContext<'_>,ent: *mut gentity_t) {
    unsafe {
        if (*ctx.world).level.time - (*ent).timestamp > BODY_SINK_TIME + 2500 {
            // the body ques are never actually freed, they are just unlinked
            trap::UnlinkEntity(ctx.engine, GUnlinkentityArgs::new(ent));
            (*ent).physicsObject = qfalse;
            return;
        }

        crate::g_utils::G_AddEvent(ent, entity_event_t::EV_BODYFADE as c_int, 0);
        (*ent).nextthink = (*ctx.world).level.time + 18000;
        (*ent).takedamage = qfalse;
    }
}

/// Raven `CopyToBodyQue` — copy a dead client into the body queue.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:996-1105`
// PORT-NOTE(fn-ptr-store-plus-traps): stores `think = BodySink`,
// `die = body_die` (still-raw fn pointers), reads `g_entities`, writes `level`,
// calls `trap_LinkEntity`/`trap_UnlinkEntity`/`trap_PointContents`/
// `trap_SendServerCommand`.
pub fn CopyToBodyQue(
    ctx: GameContext<'_>,ent: *mut gentity_t) -> qboolean {
    unsafe {
        if (*ctx.world).level.intermissiontime != 0 {
            return qfalse;
        }

        trap::UnlinkEntity(ctx.engine, GUnlinkentityArgs::new(ent));

        // if client is in a nodrop area, don't leave the body
        let contents = trap::PointContents(
            ctx.engine,
            GPointContentsArgs::new(&(*ent).s.origin as *const vec3_t, -1),
        );
        if contents & CONTENTS_NODROP != 0 {
            return qfalse;
        }

        if !(*ent).client.is_null() && (*((*ent).client as *mut gclient_t)).ps.eFlags & EF_DISINTEGRATION != 0 {
            // for now, just don't spawn a body if you got disint'd
            return qfalse;
        }

        // grab a body que and cycle to the next one
        let body = (*ctx.world).level.bodyQue[(*ctx.world).level.bodyQueIndex as usize];
        (*ctx.world).level.bodyQueIndex =
            ((*ctx.world).level.bodyQueIndex + 1) % (BODY_QUEUE_SIZE) as i32;

        trap::UnlinkEntity(ctx.engine, GUnlinkentityArgs::new(body));
        (*body).s = (*ent).s;

        // avoid oddly angled corpses floating around
        (*body).s.angles[PITCH as usize] = 0.0;
        (*body).s.angles[ROLL as usize] = 0.0;
        (*body).s.apos.trBase[PITCH as usize] = 0.0;
        (*body).s.apos.trBase[ROLL as usize] = 0.0;

        (*body).s.g2radius = 100;

        (*body).s.eType = ET_BODY as c_int;
        (*body).s.eFlags = EF_DEAD; // clear EF_TALK, etc

        if !(*ent).client.is_null() && (*((*ent).client as *mut gclient_t)).ps.eFlags & EF_DISINTEGRATION != 0 {
            (*body).s.eFlags |= EF_DISINTEGRATION;
        }

        crate::q_math::_VectorCopy((*((*ent).client as *mut gclient_t)).ps.lastHitLoc, &mut (*body).s.origin2);

        (*body).s.powerups = 0; // clear powerups
        (*body).s.loopSound = 0; // clear lava burning
        (*body).s.loopIsSoundset = qfalse;
        (*body).s.number = ent_id((*ctx.world).g_entities.as_ptr(), body).index() as c_int;
        (*body).timestamp = (*ctx.world).level.time;
        (*body).physicsObject = qtrue;
        (*body).physicsBounce = 0; // don't bounce
        if (*body).s.groundEntityNum == ENTITYNUM_NONE {
            (*body).s.pos.trType = TR_GRAVITY;
            (*body).s.pos.trTime = (*ctx.world).level.time;
            crate::q_math::_VectorCopy((*((*ent).client as *mut gclient_t)).ps.velocity, &mut (*body).s.pos.trDelta);
        } else {
            (*body).s.pos.trType = TR_STATIONARY;
        }
        (*body).s.event = 0;

        (*body).s.weapon = (*ent).s.bolt2;

        if (*body).s.weapon == WP_SABER && (*((*ent).client as *mut gclient_t)).ps.saberInFlight != 0 {
            // lie to keep from putting a saber on the corpse, because it was thrown at death
            (*body).s.weapon = WP_BLASTER;
        }

        // Now doing this through a modified version of the rcg reliable command.
        let islight = if !(*ent).client.is_null()
            && (*((*ent).client as *mut gclient_t)).ps.fd.forceSide == FORCE_LIGHTSIDE
        {
            1
        } else {
            0
        };
        let cmd = format!(
            "ircg {} {} {} {}",
            (*ent).s.number, (*body).s.number, (*body).s.weapon, islight
        );
        trap::SendServerCommand(ctx.engine, GSendServerCommandArgs::new(-1, cstr(&cmd)));

        (*body).r.svFlags = (*ent).r.svFlags | SVF_BROADCAST;
        crate::q_math::_VectorCopy((*ent).r.mins, &mut (*body).r.mins);
        crate::q_math::_VectorCopy((*ent).r.maxs, &mut (*body).r.maxs);
        crate::q_math::_VectorCopy((*ent).r.absmin, &mut (*body).r.absmin);
        crate::q_math::_VectorCopy((*ent).r.absmax, &mut (*body).r.absmax);

        (*body).s.torsoAnim = (*((*ent).client as *mut gclient_t)).ps.legsAnim;
        (*body).s.legsAnim = (*((*ent).client as *mut gclient_t)).ps.legsAnim;

        (*body).s.customRGBA[0] = (*((*ent).client as *mut gclient_t)).ps.customRGBA[0];
        (*body).s.customRGBA[1] = (*((*ent).client as *mut gclient_t)).ps.customRGBA[1];
        (*body).s.customRGBA[2] = (*((*ent).client as *mut gclient_t)).ps.customRGBA[2];
        (*body).s.customRGBA[3] = (*((*ent).client as *mut gclient_t)).ps.customRGBA[3];

        (*body).clipmask = CONTENTS_SOLID | CONTENTS_PLAYERCLIP;
        (*body).r.contents = CONTENTS_CORPSE;
        (*body).r.ownerNum = (*ent).s.number;

        (*body).nextthink = (*ctx.world).level.time + BODY_SINK_TIME;
        (*body).think = Some(EntThink::BodySink);

        (*body).die = Some(EntDie::body_die);

        // don't take more damage if already gibbed
        if (*ent).health <= GIB_HEALTH {
            (*body).takedamage = qfalse;
        } else {
            (*body).takedamage = qtrue;
        }

        crate::q_math::_VectorCopy((*body).s.pos.trBase, &mut (*body).r.currentOrigin);
        trap::LinkEntity(ctx.engine, GLinkentityArgs::new(body));

        qtrue
    }
}

/// Raven `MaintainBodyQueue`.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:1130-1159`
// PORT-NOTE(traps-plus-body-queue): calls `CopyToBodyQue` (parked), reads
// `level`, sends `va(...)`-formatted server commands via `trap_SendServerCommand`.
pub fn MaintainBodyQueue(
    ctx: GameContext<'_>,ent: *mut gentity_t) {
    unsafe {
        // do whatever should be done taking ragdoll and dismemberment states into account.
        let mut do_rcg = qfalse;

        assert!(!ent.is_null() && !(*ent).client.is_null());
        if (*((*ent).client as *mut gclient_t)).tempSpectate > (*ctx.world).level.time
            || (*((*ent).client as *mut gclient_t)).ps.eFlags2 & EF2_SHIP_DEATH != 0
        {
            (*((*ent).client as *mut gclient_t)).noCorpse = qtrue;
        }

        if (*((*ent).client as *mut gclient_t)).noCorpse == qfalse && (*((*ent).client as *mut gclient_t)).ps.fallingToDeath == qfalse {
            if CopyToBodyQue(ctx, ent) == qfalse {
                do_rcg = qtrue;
            }
        } else {
            (*((*ent).client as *mut gclient_t)).noCorpse = qfalse; // clear it for next time
            (*((*ent).client as *mut gclient_t)).ps.fallingToDeath = qfalse;
            do_rcg = qtrue;
        }

        if do_rcg != qfalse {
            // bodyque func didn't manage to call ircg so call this to assure our limbs and
            // ragdoll states are proper on the client.
            let cmd = format!("rcg {}", (*ent).s.clientNum);
            trap::SendServerCommand(ctx.engine, GSendServerCommandArgs::new(-1, cstr(&cmd)));
        }
    }
}

/// Raven `respawn` — respawn a client (or queue the body).
///
/// Source: `oracle/oracle/codemp/game/g_client.c:1167-1228`
pub fn respawn(
    ctx: GameContext<'_>,ent: *mut gentity_t) {
    unsafe {
        MaintainBodyQueue(ctx, ent);

        let client = (*ent).client as *mut gclient_t;

        if (*ctx.world).globals.gEscaping != 0
            || (*ctx.world).cvars.g_gametype.integer == GT_POWERDUEL
        {
            (*client).sess.sessionTeam = TEAM_SPECTATOR;
            (*client).sess.spectatorState = crate::client::spectator_state::spectatorState_t::SPECTATOR_FREE;
            (*client).sess.spectatorClient = 0;

            (*client).pers.teamState.state = crate::client::player_team_state::playerTeamStateState_t::TEAM_BEGIN;
            (*client).sess.spectatorTime = (*ctx.world).level.time;
            ClientSpawn(ctx, ent);
            (*client).iAmALoser = qtrue;
            return;
        }

        trap::UnlinkEntity(ctx.engine, GUnlinkentityArgs::new(ent));

        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE {
            if (*ctx.world).cvars.g_siegeRespawn.integer != 0 {
                if (*client).tempSpectate <= (*ctx.world).level.time {
                    let mut minDel = (*ctx.world).cvars.g_siegeRespawn.integer * 2000;
                    if minDel < 20000 {
                        minDel = 20000;
                    }
                    (*client).tempSpectate = (*ctx.world).level.time + minDel;
                    (*client).ps.stats[STAT_HEALTH as usize] = 1;
                    (*ent).health = 1;
                    (*client).ps.weapon = WP_NONE;
                    (*client).ps.stats[STAT_WEAPONS as usize] = 0;
                    (*client).ps.stats[STAT_HOLDABLE_ITEMS as usize] = 0;
                    (*client).ps.stats[STAT_HOLDABLE_ITEM as usize] = 0;
                    (*ent).takedamage = qfalse;
                    trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));

                    // Respawn time.
                    if (*ent).s.number < MAX_CLIENTS as c_int {
                        let te = crate::g_utils::G_TempEntity(ctx, (*client).ps.origin, entity_event_t::EV_SIEGESPEC as c_int);
                        (*te).s.time = (*ctx.world).globals.g_siegeRespawnCheck;
                        (*te).s.owner = (*ent).s.number;
                    }

                    return;
                }
            }
            crate::g_saga::SiegeRespawn(ctx, ent);
        } else {
            ClientSpawn(ctx, ent);

            // add a teleportation effect
            let tent = crate::g_utils::G_TempEntity(ctx, (*client).ps.origin, entity_event_t::EV_PLAYER_TELEPORT_IN as c_int);
            (*tent).s.clientNum = (*ent).s.clientNum;
        }
    }
}

/// Raven `TeamCount` — count players on a team.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:1237-1259`
pub fn TeamCount(
    ctx: GameContext<'_>,ignoreClientNum: c_int, team: c_int) -> team_t {
    unsafe {
        let mut count: c_int = 0;
        let mut i: c_int = 0;
        while i < (*ctx.world).level.maxclients {
            if i == ignoreClientNum {
                i += 1;
                continue;
            }
            let cl = (*ctx.world).level.clients.add(i as usize);
            if (*cl).pers.connected == CON_DISCONNECTED {
                i += 1;
                continue;
            }
            if (*cl).sess.sessionTeam == team {
                count += 1;
            } else if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE
                && (*cl).sess.siegeDesiredTeam == team
            {
                count += 1;
            }
            i += 1;
        }
        count
    }
}

/// Raven `TeamLeader` — find a team's leader client number.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:1268-1282`
pub fn TeamLeader(
    ctx: GameContext<'_>,team: c_int) -> c_int {
    unsafe {
        let mut i: c_int = 0;
        while i < (*ctx.world).level.maxclients {
            let cl = (*ctx.world).level.clients.add(i as usize);
            if (*cl).pers.connected == CON_DISCONNECTED {
                i += 1;
                continue;
            }
            if (*cl).sess.sessionTeam == team {
                if (*cl).sess.teamLeader != 0 {
                    return i;
                }
            }
            i += 1;
        }
        -1
    }
}

/// Raven `PickTeam` — pick the emptier team.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:1291-1308`
pub fn PickTeam(
    ctx: GameContext<'_>,ignoreClientNum: c_int) -> team_t {
    unsafe {
        let mut counts = [0 as c_int; TEAM_NUM_TEAMS as usize];

        counts[TEAM_BLUE as usize] = TeamCount(ctx, ignoreClientNum, TEAM_BLUE);
        counts[TEAM_RED as usize] = TeamCount(ctx, ignoreClientNum, TEAM_RED);

        if counts[TEAM_BLUE as usize] > counts[TEAM_RED as usize] {
            return TEAM_RED;
        }
        if counts[TEAM_RED as usize] > counts[TEAM_BLUE as usize] {
            return TEAM_BLUE;
        }
        // equal team count, so join the team with the lowest score
        if (*ctx.world).level.teamScores[TEAM_BLUE as usize] > (*ctx.world).level.teamScores[TEAM_RED as usize] {
            return TEAM_RED;
        }
        TEAM_BLUE
    }
}

/// Raven `ClientCleanName` — sanitize a player name (colors, spaces, length).
///
/// Source: `oracle/oracle/codemp/game/g_client.c:1335-1410`
pub fn ClientCleanName(
    ctx: GameContext<'_>,r#in: *const c_char, out: *mut c_char, outSize: c_int) {
    // Q_COLOR_ESCAPE == '^'; ColorIndex(c) == ((c - '0') & 0x07).
    const Q_COLOR_ESCAPE: c_char = b'^' as c_char;
    #[inline]
    fn ColorIndex(c: c_char) -> c_int {
        (c as c_int - '0' as c_int) & 0x07
    }
    unsafe {
        // save room for trailing null byte
        let outSize = outSize - 1;

        let mut len: c_int = 0;
        let mut colorlessLen: c_int = 0;
        let p = out; // start of dest
        *p = 0;
        let mut spaces: c_int = 0;

        let mut inp = r#in;
        let mut outp = out;

        loop {
            let ch = *inp;
            inp = inp.add(1);
            if ch == 0 {
                break;
            }

            // don't allow leading spaces
            if *p == 0 && ch == b' ' as c_char {
                continue;
            }

            // check colors
            if ch == Q_COLOR_ESCAPE {
                // solo trailing carat is not a color prefix
                if *inp == 0 {
                    break;
                }

                // don't allow black in a name, period
                if ColorIndex(*inp) == 0 {
                    inp = inp.add(1);
                    continue;
                }

                // make sure room in dest for both chars
                if len > outSize - 2 {
                    break;
                }

                *outp = ch;
                outp = outp.add(1);
                *outp = *inp;
                outp = outp.add(1);
                inp = inp.add(1);
                len += 2;
                continue;
            }

            // don't allow too many consecutive spaces
            if ch == b' ' as c_char {
                spaces += 1;
                if spaces > 3 {
                    continue;
                }
            } else {
                spaces = 0;
            }

            if len > outSize - 1 {
                break;
            }

            *outp = ch;
            outp = outp.add(1);
            colorlessLen += 1;
            len += 1;
        }
        *outp = 0;

        // don't allow empty names
        if *p == 0 || colorlessLen == 0 {
            crate::q_shared::Q_strncpyz(p, b"Padawan\0".as_ptr() as *const c_char, outSize);
        }
    }
}

/// Raven `G_SaberModelSetup`.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:1423-1499`
// PORT-NOTE(g2-ghoul2-traps): builds the saber ghoul2 models via
// `trap_G2API_*` (AddBolt/CleanGhoul2Models/CopySpecificGhoul2Model/
// InitGhoul2Model/SetBoltInfo/SetSkin); the ghoul2 handle threading + Args
// constructors are not resolved in this packet.
pub fn G_SaberModelSetup(
    ctx: GameContext<'_>,ent: *mut gentity_t) -> qboolean {
    use mp_abi::game::syscalls::G_G2_ADDBOLT::GG2AddboltArgs;
    use mp_abi::game::syscalls::G_G2_CLEANMODELS::GG2CleanmodelsArgs;
    use mp_abi::game::syscalls::G_G2_COPYSPECIFICGHOUL2MODEL::GG2Copyspecificghoul2ModelArgs;
    use mp_abi::game::syscalls::G_G2_INITGHOUL2MODEL::GG2Initghoul2ModelArgs;
    use mp_abi::game::syscalls::G_G2_SETBOLTINFO::GG2SetboltinfoArgs;
    use mp_abi::game::syscalls::G_G2_SETSKIN::GG2SetskinArgs;

    unsafe {
        let mut i: usize = 0;
        let mut fallback_for_saber = qtrue;

        while i < MAX_SABERS as usize {
            if (*((*ent).client as *mut gclient_t)).saber[i].model[0] != 0 {
                // first kill it off if we've already got it
                if !(*((*ent).client as *mut gclient_t)).weaponGhoul2[i].is_null() {
                    trap::G2API_CleanGhoul2Models(
                        ctx.engine,
                        GG2CleanmodelsArgs::new(
                            &mut (*((*ent).client as *mut gclient_t)).weaponGhoul2[i] as *mut *mut c_void,
                        ),
                    );
                }
                let model_name = cstr_to_str((*((*ent).client as *mut gclient_t)).saber[i].model.as_ptr());
                trap::G2API_InitGhoul2Model(
                    ctx.engine,
                    GG2Initghoul2ModelArgs::new(
                        &mut (*((*ent).client as *mut gclient_t)).weaponGhoul2[i] as *mut *mut c_void,
                        cstr(&model_name),
                        0,
                        0,
                        -20,
                        0,
                        0,
                    ),
                );

                if !(*((*ent).client as *mut gclient_t)).weaponGhoul2[i].is_null() {
                    let mut j: usize = 0;
                    let mut tag_bolt: c_int;

                    if (*((*ent).client as *mut gclient_t)).saber[i].skin != 0 {
                        trap::G2API_SetSkin(
                            ctx.engine,
                            GG2SetskinArgs::new(
                                (*((*ent).client as *mut gclient_t)).weaponGhoul2[i],
                                0,
                                (*((*ent).client as *mut gclient_t)).saber[i].skin,
                                (*((*ent).client as *mut gclient_t)).saber[i].skin,
                            ),
                        );
                    }

                    if (*((*ent).client as *mut gclient_t)).saber[i].saberFlags & SFL_BOLT_TO_WRIST != 0 {
                        trap::G2API_SetBoltInfo(
                            ctx.engine,
                            GG2SetboltinfoArgs::new(
                                (*((*ent).client as *mut gclient_t)).weaponGhoul2[i],
                                0,
                                3 + i as c_int,
                            ),
                        );
                    } else {
                        // bolt to right hand for 0, or left hand for 1
                        trap::G2API_SetBoltInfo(
                            ctx.engine,
                            GG2SetboltinfoArgs::new(
                                (*((*ent).client as *mut gclient_t)).weaponGhoul2[i],
                                0,
                                i as c_int,
                            ),
                        );
                    }

                    // Add all the bolt points
                    while j < (*((*ent).client as *mut gclient_t)).saber[i].numBlades as usize {
                        let tag_name = format!("*blade{}", j + 1);
                        tag_bolt = trap::G2API_AddBolt(
                            ctx.engine,
                            GG2AddboltArgs::new(
                                (*((*ent).client as *mut gclient_t)).weaponGhoul2[i],
                                0,
                                cstr(&tag_name),
                            ),
                        );

                        if tag_bolt == -1 {
                            if j == 0 {
                                // guess this is an 0ldsk3wl saber
                                let _ = trap::G2API_AddBolt(
                                    ctx.engine,
                                    GG2AddboltArgs::new(
                                        (*((*ent).client as *mut gclient_t)).weaponGhoul2[i],
                                        0,
                                        cstr("*flash"),
                                    ),
                                );
                                fallback_for_saber = qfalse;
                                break;
                            }

                            if tag_bolt == -1 {
                                assert!(false);
                                break;
                            }
                        }
                        j += 1;

                        // got at least one custom saber so don't need default
                        fallback_for_saber = qfalse;
                    }

                    // Copy it into the main instance
                    trap::G2API_CopySpecificGhoul2Model(
                        ctx.engine,
                        GG2Copyspecificghoul2ModelArgs::new(
                            (*((*ent).client as *mut gclient_t)).weaponGhoul2[i],
                            0,
                            (*ent).ghoul2,
                            i as c_int + 1,
                        ),
                    );
                }
            } else {
                break;
            }

            i += 1;
        }

        fallback_for_saber
    }
}

/// Raven `ClientConnect`.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:2258-2373`
// PORT-NOTE(multi-global-trap-va-cluster): `trap_GetUserinfo`/
// `trap_SendServerCommand` + `va(...)`, session/bot init, reads
// `g_entities`/`g_gametype`/`g_needpass`/`g_password`/`level`; returns a raw
// `*mut c_char` into a fn-scope static buffer (fork 5) that the raw-ptr
// signature cannot own.
pub fn ClientConnect(
    ctx: GameContext<'_>,clientNum: c_int, firstTime: qboolean, isBot: qboolean) -> *mut c_char {
    unsafe {
        let ent = (*ctx.world).g_entities.as_mut_ptr().add(clientNum as usize);

        let mut userinfo_buf = [0i8; MAX_INFO_STRING as usize];
        trap::GetUserinfo(
            ctx.engine,
            mp_abi::game::syscalls::G_GET_USERINFO::GGetUserinfoArgs::new(
                clientNum,
                userinfo_buf.as_mut_ptr(),
                (MAX_INFO_STRING) as i32,
            ),
        );
        let userinfo = cstr_to_str(userinfo_buf.as_ptr());

        // check to see if they are on the banned IP list
        let value = cstr_to_str(Info_ValueForKey(cstr(&userinfo).as_ptr(), cstr("ip").as_ptr()));
        let ip_string = value.clone();

        if crate::g_svcmds::G_FilterPacket(ctx, cstr(&value).as_ptr() as *mut c_char) != qfalse {
            return b"Banned.\0".as_ptr() as *mut c_char;
        }

        if (*ent).r.svFlags & SVF_BOT == 0
            && isBot == qfalse
            && (*ctx.world).cvars.g_needpass.integer != 0
        {
            // check for a password
            let value = cstr_to_str(Info_ValueForKey(cstr(&userinfo).as_ptr(), cstr("password").as_ptr()));
            let g_password = cstr_to_str((*ctx.world).cvars.g_password.string.as_ptr());
            if !g_password.is_empty()
                && !g_password.eq_ignore_ascii_case("none")
                && g_password != value
            {
                // PORT-NOTE(static-buffer): Raven returns a `static char sTemp[1024]`;
                // returning a leaked/owned buffer is the faithful-behavior stand-in.
                let s = cstr_to_str(G_GetStringEdString(
                    ctx,
                    c"MP_SVGAME".as_ptr() as *mut c_char,
                    c"INVALID_ESCAPE_TO_MAIN".as_ptr() as *mut c_char,
                ));
                return cstr(&s).into_raw();
            }
        }

        // they can connect
        (*ent).client = (*ctx.world).clients.as_mut_ptr().add(clientNum as usize) as *mut c_void;
        let client = (*ent).client as *mut gclient_t;

        // assign the pointer for bg entity access
        (*ent).playerState = &mut (*client).ps;

        core::ptr::write_bytes(client, 0, 1);

        (*client).pers.connected = CON_CONNECTING as _;

        // read or initialize the session data
        if firstTime != qfalse || (*ctx.world).level.newSession != qfalse {
            G_InitSessionData(ctx, client, cstr(&userinfo).as_ptr() as *mut c_char, isBot);
        }
        G_ReadSessionData(ctx, client);

        write_cstr_field(&mut (*client).sess.IPstring, &ip_string);

        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE
            && (firstTime != qfalse || (*ctx.world).level.newSession != qfalse)
        {
            // if this is the first time then auto-assign a desired siege team and show
            // briefing for that team
            (*client).sess.siegeDesiredTeam = 0;
        }

        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE
            && (*client).sess.sessionTeam != TEAM_SPECTATOR
        {
            if firstTime != qfalse || (*ctx.world).level.newSession != qfalse {
                // start as spec
                (*client).sess.siegeDesiredTeam = (*client).sess.sessionTeam as c_int;
                (*client).sess.sessionTeam = TEAM_SPECTATOR;
            }
        } else if (*ctx.world).cvars.g_gametype.integer == GT_POWERDUEL
            && (*client).sess.sessionTeam != TEAM_SPECTATOR
        {
            (*client).sess.sessionTeam = TEAM_SPECTATOR;
        }

        if isBot != qfalse {
            (*ent).r.svFlags |= SVF_BOT;
            (*ent).inuse = qtrue;
            if crate::g_bot::G_BotConnect(ctx, clientNum, (firstTime == qfalse) as qboolean) == qfalse {
                return b"BotConnectfailed\0".as_ptr() as *mut c_char;
            }
        }

        // get and distribute relevant parameters
        G_LogPrintf(ctx, cstr(&format!("ClientConnect: {}\n", clientNum)).as_ptr());
        ClientUserinfoChanged(ctx, clientNum);
        G_LogPrintf(
            ctx,
            cstr(&format!(
                "{} connected with IP: {}\n",
                cstr_to_str((*client).pers.netname.as_ptr()),
                cstr_to_str((*client).sess.IPstring.as_ptr()),
            ))
            .as_ptr(),
        );

        // don't do the "xxx connected" messages if they were carried over from previous level
        if firstTime != qfalse {
            let m = format!(
                "print \"{}{} {}\n\"",
                cstr_to_str((*client).pers.netname.as_ptr()),
                S_COLOR_WHITE,
                cstr_to_str(G_GetStringEdString(
                    ctx,
                    c"MP_SVGAME".as_ptr() as *mut c_char,
                    c"PLCONNECT".as_ptr() as *mut c_char,
                )),
            );
            trap::SendServerCommand(ctx.engine, GSendServerCommandArgs::new(-1, cstr(&m)));
        }

        if (*ctx.world).cvars.g_gametype.integer >= GT_TEAM
            && (*client).sess.sessionTeam != TEAM_SPECTATOR
        {
            BroadcastTeamChange(ctx, client, -1);
        }

        // count current clients and rank for scoreboard
        CalculateRanks(ctx);

        let te = G_TempEntity(ctx, [0.0, 0.0, 0.0], (EV_CLIENTJOIN) as i32);
        (*te).r.svFlags |= SVF_BROADCAST;
        (*te).s.eventParm = clientNum;

        core::ptr::null_mut()
    }
}

/// Raven `ClientBegin`.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:2393-2593`
// PORT-NOTE(multi-global-trap-va-cluster): traps
// (`trap_GetUserinfo`/`trap_SetUserinfo`/`trap_SendServerCommand`/
// `trap_UnlinkEntity`), `va(...)`, `ClientSpawn`/`SetTeam`/`SetupGameGhoul2Model`
// (parked), reads `gSiegeRound*`/`g_entities`/`g_gametype`/`level`.
pub fn ClientBegin(
    ctx: GameContext<'_>,clientNum: c_int, allowTeamReset: qboolean) {
    unsafe {
        let ent = (*ctx.world).g_entities.as_mut_ptr().add(clientNum as usize);

        if (*ent).r.svFlags & SVF_BOT != 0 && (*ctx.world).cvars.g_gametype.integer >= GT_TEAM {
            if allowTeamReset != qfalse {
                let mut team_str = "Red";

                (*((*ent).client as *mut gclient_t)).sess.sessionTeam = PickTeam(ctx, -1);
                let mut userinfo_buf = [0i8; MAX_INFO_STRING as usize];
                trap::GetUserinfo(
                    ctx.engine,
                    mp_abi::game::syscalls::G_GET_USERINFO::GGetUserinfoArgs::new(
                        clientNum,
                        userinfo_buf.as_mut_ptr(),
                        (MAX_INFO_STRING) as i32,
                    ),
                );
                let mut userinfo = cstr_to_str(userinfo_buf.as_ptr());

                if (*((*ent).client as *mut gclient_t)).sess.sessionTeam == TEAM_SPECTATOR {
                    (*((*ent).client as *mut gclient_t)).sess.sessionTeam = TEAM_RED;
                }

                if (*((*ent).client as *mut gclient_t)).sess.sessionTeam == TEAM_RED {
                    team_str = "Red";
                } else {
                    team_str = "Blue";
                }

                Info_SetValueForKey(
                    cstr(&userinfo).as_ptr() as *mut c_char,
                    c"team".as_ptr(),
                    cstr(team_str).as_ptr(),
                );

                trap::SetUserinfo(
                    ctx.engine,
                    mp_abi::game::syscalls::G_SET_USERINFO::GSetUserinfoArgs::new(
                        clientNum,
                        cstr(&userinfo),
                    ),
                );

                (*((*ent).client as *mut gclient_t)).ps.persistant[PERS_TEAM as usize] =
                    (*((*ent).client as *mut gclient_t)).sess.sessionTeam as c_int;

                let pre_sess = (*((*ent).client as *mut gclient_t)).sess.sessionTeam;
                G_ReadSessionData(ctx, (*ent).client as *mut gclient_t);
                (*((*ent).client as *mut gclient_t)).sess.sessionTeam = pre_sess;
                G_WriteClientSessionData(ctx, (*ent).client as *mut gclient_t);
                ClientUserinfoChanged(ctx, clientNum);
                ClientBegin(ctx, clientNum, qfalse);
                return;
            }
        }

        let client = (*ctx.world).clients.as_mut_ptr().add(clientNum as usize);

        if (*ent).r.linked != qfalse {
            trap::UnlinkEntity(ctx.engine, GUnlinkentityArgs::new(ent));
        }
        crate::g_utils::G_InitGentity(ctx, ent);
        (*ent).touch = None;
        (*ent).pain = None;
        (*ent).client = client as *mut c_void;

        // assign the pointer for bg entity access
        (*ent).playerState = &mut (*((*ent).client as *mut gclient_t)).ps;

        (*client).pers.connected = CON_CONNECTED as _;
        (*client).pers.enterTime = (*ctx.world).level.time;
        (*client).pers.teamState.state = crate::client::player_team_state::playerTeamStateState_t::TEAM_BEGIN;

        // save eflags around this, because changing teams will cause this to happen with a
        // valid entity, and we want to make sure the teleport bit is set right so the
        // viewpoint doesn't interpolate through the world to the new position
        let flags = (*client).ps.eFlags;

        let mut i = 0;
        while i < NUM_FORCE_POWERS {
            if (*((*ent).client as *mut gclient_t)).ps.fd.forcePowersActive & (1 << i) != 0 {
                WP_ForcePowerStop(ctx, ent, i as forcePowers_t);
            }
            i += 1;
        }

        i = (TRACK_CHANNEL_1) as usize;
        while i < (NUM_TRACK_CHANNELS) as usize {
            let idx = (i - 50) as usize;
            if (*((*ent).client as *mut gclient_t)).ps.fd.killSoundEntIndex[idx] != 0
                && (*((*ent).client as *mut gclient_t)).ps.fd.killSoundEntIndex[idx] < MAX_GENTITIES as c_int
                && (*((*ent).client as *mut gclient_t)).ps.fd.killSoundEntIndex[idx] > 0
            {
                G_MuteSound(ctx, (*((*ent).client as *mut gclient_t)).ps.fd.killSoundEntIndex[idx], CHAN_VOICE);
            }
            i += 1;
        }

        let ps_ptr = &mut (*client).ps as *mut playerState_t;
        core::ptr::write_bytes(ps_ptr, 0, 1);
        (*client).ps.eFlags = flags;

        (*client).ps.hasDetPackPlanted = qfalse;

        // first-time force power initialization
        WP_InitForcePowers(ctx, ent);

        // init saber ent
        crate::w_saber::WP_SaberInitBladeData(ctx, ent);

        // First time model setup for that player.
        let mut userinfo_buf = [0i8; MAX_INFO_STRING as usize];
        trap::GetUserinfo(
            ctx.engine,
            mp_abi::game::syscalls::G_GET_USERINFO::GGetUserinfoArgs::new(
                clientNum,
                userinfo_buf.as_mut_ptr(),
                (MAX_INFO_STRING) as i32,
            ),
        );
        let userinfo = cstr_to_str(userinfo_buf.as_ptr());
        let modelname = Info_ValueForKey(cstr(&userinfo).as_ptr(), cstr("model").as_ptr());
        SetupGameGhoul2Model(ctx, ent, modelname, core::ptr::null_mut());

        if (*ctx.world).cvars.g_gametype.integer == GT_POWERDUEL
            && (*client).sess.sessionTeam != TEAM_SPECTATOR
            && (*client).sess.duelTeam == DUELTEAM_FREE as c_int
        {
            SetTeam(ctx, ent, c"s".as_ptr() as *mut c_char);
        } else {
            if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE
                && ((*ctx.world).globals.gSiegeRoundBegun == qfalse
                    || (*ctx.world).globals.gSiegeRoundEnded != qfalse)
            {
                SetTeamQuick(ctx, ent, TEAM_SPECTATOR as c_int, qfalse);
            }

            if (*ent).r.svFlags & SVF_BOT != 0 && (*ctx.world).cvars.g_gametype.integer != GT_SIEGE {
                let saber_val = Info_ValueForKey(cstr(&userinfo).as_ptr(), cstr("saber1").as_ptr());
                let saber2_val = Info_ValueForKey(cstr(&userinfo).as_ptr(), cstr("saber2").as_ptr());

                if saber_val.is_null() || *saber_val == 0 {
                    // blah, set em up with a random saber
                    let r = (*ctx.world).bg_state.rng.rand() % 50;
                    let (sab1, sab2);
                    if r <= 17 {
                        sab1 = "Katarn";
                        sab2 = "none";
                    } else if r <= 34 {
                        sab1 = "Katarn";
                        sab2 = "Katarn";
                    } else {
                        sab1 = "dual_1";
                        sab2 = "none";
                    }
                    G_SetSaber(ctx, ent, 0, cstr(sab1).as_ptr() as *mut c_char, qfalse);
                    G_SetSaber(ctx, ent, 0, cstr(sab2).as_ptr() as *mut c_char, qfalse);
                    let mut userinfo_mut = userinfo.clone();
                    Info_SetValueForKey(
                        cstr(&userinfo_mut).as_ptr() as *mut c_char,
                        c"saber1".as_ptr(),
                        cstr(sab1).as_ptr(),
                    );
                    Info_SetValueForKey(
                        cstr(&userinfo_mut).as_ptr() as *mut c_char,
                        c"saber2".as_ptr(),
                        cstr(sab2).as_ptr(),
                    );
                    trap::SetUserinfo(
                        ctx.engine,
                        mp_abi::game::syscalls::G_SET_USERINFO::GSetUserinfoArgs::new(
                            clientNum,
                            cstr(&userinfo_mut),
                        ),
                    );
                } else {
                    G_SetSaber(ctx, ent, 0, saber_val, qfalse);
                }

                if !saber_val.is_null() && *saber_val != 0 && (saber2_val.is_null() || *saber2_val == 0) {
                    G_SetSaber(ctx, ent, 0, c"none".as_ptr() as *mut c_char, qfalse);
                    let mut userinfo_mut = userinfo.clone();
                    Info_SetValueForKey(
                        cstr(&userinfo_mut).as_ptr() as *mut c_char,
                        c"saber2".as_ptr(),
                        c"none".as_ptr(),
                    );
                    trap::SetUserinfo(
                        ctx.engine,
                        mp_abi::game::syscalls::G_SET_USERINFO::GSetUserinfoArgs::new(
                            clientNum,
                            cstr(&userinfo_mut),
                        ),
                    );
                } else {
                    G_SetSaber(ctx, ent, 0, saber2_val, qfalse);
                }
            }

            // locate ent at a spawn point
            ClientSpawn(ctx, ent);
        }

        if (*client).sess.sessionTeam != TEAM_SPECTATOR {
            // send event
            let tent = G_TempEntity(ctx, (*client).ps.origin, (EV_PLAYER_TELEPORT_IN) as i32);
            (*tent).s.clientNum = (*ent).s.clientNum;

            if (*ctx.world).cvars.g_gametype.integer != GT_DUEL
                || (*ctx.world).cvars.g_gametype.integer == GT_POWERDUEL
            {
                let m = format!(
                    "print \"{}{} {}\n\"",
                    cstr_to_str((*client).pers.netname.as_ptr()),
                    S_COLOR_WHITE,
                    cstr_to_str(G_GetStringEdString(
                        ctx,
                        c"MP_SVGAME".as_ptr() as *mut c_char,
                        c"PLENTER".as_ptr() as *mut c_char,
                    )),
                );
                trap::SendServerCommand(ctx.engine, GSendServerCommandArgs::new(-1, cstr(&m)));
            }
        }
        G_LogPrintf(ctx, cstr(&format!("ClientBegin: {}\n", clientNum)).as_ptr());

        // count current clients and rank for scoreboard
        CalculateRanks(ctx);

        crate::g_log::G_ClearClientLog(ctx, clientNum);
    }
}

/// Raven `AllForceDisabled` — are all force powers disabled by the mask?
///
/// Source: `oracle/oracle/codemp/game/g_client.c:2595-2613`
pub fn AllForceDisabled(force: c_int) -> qboolean {
    if force != 0 {
        for i in 0..NUM_FORCE_POWERS {
            if force & (1 << i) == 0 {
                return qfalse;
            }
        }
        return qtrue;
    }

    qfalse
}

/// Raven `G_BreakArm` — set up a broken-limb state and pain animation.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:2616-2674`
// PORT-NOTE(va-varargs-plus-rng): builds a sound name with `va(...)` +
// `Q_irand(1,3)` (the resolved `va` drops the C varargs, and `Q_irand` is part
// of the threaded-RNG surface, fork ruling 3).
pub fn G_BreakArm(
    ctx: GameContext<'_>,ent: *mut gentity_t, arm: c_int) {
    unsafe {
        let mut anim: c_int = -1;

        assert!(!ent.is_null() && !(*ent).client.is_null());

        if (*ent).s.NPC_class == CLASS_VEHICLE as c_int || (*ent).localAnimIndex > 1 {
            // no broken limbs for vehicles and non-humanoids
            return;
        }

        if arm == 0 {
            // repair him
            (*((*ent).client as *mut gclient_t)).ps.brokenLimbs = 0;
            return;
        }

        if (*((*ent).client as *mut gclient_t)).ps.fd.saberAnimLevel == SS_STAFF as c_int {
            // I'm too lazy to deal with this as well for now.
            return;
        }

        if arm == (BROKENLIMB_LARM) as i32 {
            if (*((*ent).client as *mut gclient_t)).saber[1].model[0] != 0
                && (*((*ent).client as *mut gclient_t)).ps.weapon == WP_SABER
                && (*((*ent).client as *mut gclient_t)).ps.saberHolstered == 0
                && (*((*ent).client as *mut gclient_t)).saber[1].soundOff != 0
            {
                // the left arm shuts off its saber upon being broken
                G_Sound(ctx, ent, CHAN_AUTO, (*((*ent).client as *mut gclient_t)).saber[1].soundOff);
            }
        }

        (*((*ent).client as *mut gclient_t)).ps.brokenLimbs = 0; // make sure it's cleared out
        (*((*ent).client as *mut gclient_t)).ps.brokenLimbs |= 1 << arm; // this arm is now marked as broken

        // Do a pain anim based on the side. Since getting your arm broken does tend to hurt.
        if arm == (BROKENLIMB_LARM) as i32 {
            anim = (BOTH_PAIN2) as i32;
        } else if arm == (BROKENLIMB_RARM) as i32 {
            anim = (BOTH_PAIN3) as i32;
        }

        if anim == -1 {
            return;
        }

        G_SetAnim(
            ent,
            &mut (*((*ent).client as *mut gclient_t)).pers.cmd as *mut usercmd_t,
            SETANIM_BOTH,
            anim,
            SETANIM_FLAG_OVERRIDE | SETANIM_FLAG_HOLD,
            0,
        );

        // This could be combined into a single event. But I guess limbs don't break often
        // enough to worry about it.
        G_EntitySound(ctx, ent, CHAN_VOICE, G_SoundIndex(cstr("*pain25.wav").as_ptr()));
        // FIXME: A nice bone snapping sound instead if possible
        let n = (*ctx.world).bg_state.rng.Q_irand(1, 3);
        G_Sound(
            ctx,
            ent,
            CHAN_AUTO,
            G_SoundIndex(cstr(&format!("sound/player/bodyfall_human{}.wav", n)).as_ptr()),
        );
    }
}

/// Raven `G_UpdateClientAnims`.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:2681-2926`
// PORT-NOTE(g2-trap-plus-bg): drives torso/legs bone anims via
// `trap_G2API_SetBoneAnim` and `BG_SaberStartTransAnim`, reads
// `bgAllAnims`/`level`; ghoul2 handle threading unresolved here.
pub fn G_UpdateClientAnims(
    ctx: GameContext<'_>,self_: *mut gentity_t, mut animSpeedScale: f32) {
    use mp_abi::game::syscalls::G_G2_PLAYANIM::GG2PlayanimArgs as GG2SetboneanimArgs;

    // PORT-NOTE(dead-code): the `#if 0` broken-limb bone block (g_client.c:2804-2925)
    // is disabled in the oracle itself — dropped per §20.
    unsafe {
        let torso_anim = ((*self_).client as *mut gclient_t).as_ref().unwrap().ps.torsoAnim;
        let legs_anim = (*((*self_).client as *mut gclient_t)).ps.legsAnim;
        let mut set_torso = qfalse;
        let mut first_frame: c_int = 0;
        let mut last_frame: c_int = 0;
        let mut a_flags: c_int;
        let mut anim_speed: f64;
        let mut l_anim_speed_scale: f32;

        if (*((*self_).client as *mut gclient_t)).ps.saberLockFrame != 0 {
            let frame = (*((*self_).client as *mut gclient_t)).ps.saberLockFrame;
            trap::G2API_SetBoneAnim(
                ctx.engine,
                GG2SetboneanimArgs::new(
                    (*self_).ghoul2, 0, cstr("model_root").as_ptr(), frame, frame + 1,
                    BONE_ANIM_OVERRIDE_FREEZE | BONE_ANIM_BLEND, animSpeedScale,
                    (*ctx.world).level.time, -1.0, 150,
                ),
            );
            trap::G2API_SetBoneAnim(
                ctx.engine,
                GG2SetboneanimArgs::new(
                    (*self_).ghoul2, 0, cstr("lower_lumbar").as_ptr(), frame, frame + 1,
                    BONE_ANIM_OVERRIDE_FREEZE | BONE_ANIM_BLEND, animSpeedScale,
                    (*ctx.world).level.time, -1.0, 150,
                ),
            );
            trap::G2API_SetBoneAnim(
                ctx.engine,
                GG2SetboneanimArgs::new(
                    (*self_).ghoul2, 0, cstr("Motion").as_ptr(), frame, frame + 1,
                    BONE_ANIM_OVERRIDE_FREEZE | BONE_ANIM_BLEND, animSpeedScale,
                    (*ctx.world).level.time, -1.0, 150,
                ),
            );
            return;
        }

        let all_anims = &(*ctx.world).bg_state.bgAllAnims[(*self_).localAnimIndex as usize];

        let skip_legs = (*self_).localAnimIndex > 1
            && all_anims.anims[legs_anim as usize].firstFrame == 0
            && all_anims.anims[legs_anim as usize].numFrames == 0;

        if !skip_legs {
            if (*((*self_).client as *mut gclient_t)).legsAnimExecute != legs_anim
                || (*((*self_).client as *mut gclient_t)).legsLastFlip != (*((*self_).client as *mut gclient_t)).ps.legsFlip
            {
                let anim = &all_anims.anims[legs_anim as usize];
                anim_speed = 50.0f32 as f64 / anim.frameLerp as f64;
                anim_speed *= animSpeedScale as f64;
                l_anim_speed_scale = anim_speed as f32;

                a_flags = if anim.loopFrames != -1 {
                    BONE_ANIM_OVERRIDE_LOOP
                } else {
                    BONE_ANIM_OVERRIDE_FREEZE
                };

                if anim_speed < 0.0 {
                    last_frame = anim.firstFrame;
                    first_frame = anim.firstFrame + anim.numFrames;
                } else {
                    first_frame = anim.firstFrame;
                    last_frame = anim.firstFrame + anim.numFrames;
                }

                a_flags |= BONE_ANIM_BLEND;

                trap::G2API_SetBoneAnim(
                    ctx.engine,
                    GG2SetboneanimArgs::new(
                        (*self_).ghoul2, 0, cstr("model_root").as_ptr(), first_frame, last_frame,
                        a_flags, l_anim_speed_scale, (*ctx.world).level.time, -1.0, 150,
                    ),
                );
                (*((*self_).client as *mut gclient_t)).legsAnimExecute = legs_anim;
                (*((*self_).client as *mut gclient_t)).legsLastFlip = (*((*self_).client as *mut gclient_t)).ps.legsFlip;
            }
        }

        // tryTorso:
        let all_anims = &(*ctx.world).bg_state.bgAllAnims[(*self_).localAnimIndex as usize];
        if (*self_).localAnimIndex > 1
            && all_anims.anims[torso_anim as usize].firstFrame == 0
            && all_anims.anims[torso_anim as usize].numFrames == 0
        {
            // If this fails as well just return.
            return;
        } else if (*self_).s.number >= MAX_CLIENTS as c_int
            && (*self_).s.NPC_class == CLASS_VEHICLE as c_int
        {
            // we only want to set the root bone for vehicles
            return;
        }

        let (mut a_flags2, mut first2, mut last2, mut speed2) = (0, 0, 0, 0.0f32);

        if ((*((*self_).client as *mut gclient_t)).torsoAnimExecute != torso_anim
            || (*((*self_).client as *mut gclient_t)).torsoLastFlip != (*((*self_).client as *mut gclient_t)).ps.torsoFlip)
            && (*self_).noLumbar == qfalse
        {
            let mut f = torso_anim;

            crate::bg_panimate::BG_SaberStartTransAnim(
                (*self_).s.number,
                (*((*self_).client as *mut gclient_t)).ps.fd.saberAnimLevel,
                (*((*self_).client as *mut gclient_t)).ps.weapon,
                f,
                &mut animSpeedScale as *mut f32,
                (*((*self_).client as *mut gclient_t)).ps.brokenLimbs,
            );

            let all_anims = &(*ctx.world).bg_state.bgAllAnims[(*self_).localAnimIndex as usize];
            let anim = &all_anims.anims[f as usize];
            anim_speed = 50.0f32 as f64 / anim.frameLerp as f64;
            anim_speed *= animSpeedScale as f64;
            speed2 = anim_speed as f32;

            a_flags2 = if anim.loopFrames != -1 {
                BONE_ANIM_OVERRIDE_LOOP
            } else {
                BONE_ANIM_OVERRIDE_FREEZE
            };
            a_flags2 |= BONE_ANIM_BLEND;

            if anim_speed < 0.0 {
                last2 = anim.firstFrame;
                first2 = anim.firstFrame + anim.numFrames;
            } else {
                first2 = anim.firstFrame;
                last2 = anim.firstFrame + anim.numFrames;
            }

            trap::G2API_SetBoneAnim(
                ctx.engine,
                GG2SetboneanimArgs::new(
                    (*self_).ghoul2, 0, cstr("lower_lumbar").as_ptr(), first2, last2, a_flags2,
                    speed2, (*ctx.world).level.time, -1.0, 150,
                ),
            );

            (*((*self_).client as *mut gclient_t)).torsoAnimExecute = torso_anim;
            (*((*self_).client as *mut gclient_t)).torsoLastFlip = (*((*self_).client as *mut gclient_t)).ps.torsoFlip;

            set_torso = qtrue;
            first_frame = first2;
            last_frame = last2;
            a_flags = a_flags2;
            l_anim_speed_scale = speed2;
        } else {
            a_flags = a_flags2;
            l_anim_speed_scale = speed2;
        }

        if set_torso != qfalse && (*self_).localAnimIndex <= 1 {
            // only set the motion bone for humanoids.
            trap::G2API_SetBoneAnim(
                ctx.engine,
                GG2SetboneanimArgs::new(
                    (*self_).ghoul2, 0, cstr("Motion").as_ptr(), first_frame, last_frame, a_flags,
                    l_anim_speed_scale, (*ctx.world).level.time, -1.0, 150,
                ),
            );
        }
    }
}

/// Raven `ClientSpawn` — spawn/respawn a client into the world (864 LOC).
///
/// Source: `oracle/oracle/codemp/game/g_client.c:2938-3801`
// PORT-NOTE(mega-fn-globals-traps-bg-fnptr): the largest function in the
// file — ~18 cvars, `g_entities`/`level`/`playerMins`/`playerMaxs`/`ammoData`/
// `weaponData`/`WeaponReadyAnim`/`bgSiegeClasses` globals, many traps
// (`trap_Cvar_Set`/`trap_GetUsercmd`/`trap_GetUserinfo`/`trap_SetUserinfo`/
// `trap_ICARUS_*`/`trap_LinkEntity`), `BG_*`/`WP_*` calls, `va(...)`, and stores
// `die = player_die` (still-raw fn pointer). Beyond safe single-porter
// transcription without compilation; integration to thread the spine.
pub fn ClientSpawn(
    ctx: GameContext<'_>,ent: *mut gentity_t) {
    unsafe {
        let index = ent_id((*ctx.world).g_entities.as_ptr(), ent).index() as c_int;
        let client = (*ent).client as *mut gclient_t;

        // first we want the userinfo so we can see if we should update this client's saber
        let mut userinfo_buf = [0i8; MAX_INFO_STRING as usize];
        trap::GetUserinfo(
            ctx.engine,
            mp_abi::game::syscalls::G_GET_USERINFO::GGetUserinfoArgs::new(
                index,
                userinfo_buf.as_mut_ptr(),
                (MAX_INFO_STRING) as i32,
            ),
        );
        let mut userinfo = cstr_to_str(userinfo_buf.as_ptr());
        let mut changed_saber = qfalse;

        let mut l: c_int = 0;
        while l < (MAX_SABERS) as i32 {
            let saber = match l {
                0 => Some(cstr_to_str((*client).sess.saberType.as_ptr())),
                1 => Some(cstr_to_str((*client).sess.saber2Type.as_ptr())),
                _ => None,
            };

            let key = format!("saber{}", l + 1);
            let value = Info_ValueForKey(cstr(&userinfo).as_ptr(), cstr(&key).as_ptr());
            if let Some(ref saber) = saber {
                if !value.is_null() {
                    let value_s = cstr_to_str(value);
                    if !value_s.eq_ignore_ascii_case(saber)
                        || saber.is_empty()
                        || (*client).saber[0].model[0] == 0
                    {
                        if G_SetSaber(ctx, ent, l, cstr(&value_s).as_ptr() as *mut c_char, qfalse) != qfalse {
                            changed_saber = qtrue;
                        } else if saber.is_empty() || (*client).saber[0].model[0] == 0 {
                            changed_saber = qtrue;
                        }
                    }
                }
            }
            l += 1;
        }

        if changed_saber != qfalse {
            // make sure our new info is sent out to all the other clients, and give us a
            // valid stance
            ClientUserinfoChanged(ctx, (*ent).s.number);

            // make sure the saber models are updated
            G_SaberModelSetup(ctx, ent);

            l = 0;
            while l < (MAX_SABERS) as i32 {
                let saber = match l {
                    0 => Some(cstr_to_str((*client).sess.saberType.as_ptr())),
                    1 => Some(cstr_to_str((*client).sess.saber2Type.as_ptr())),
                    _ => None,
                };
                let key = format!("saber{}", l + 1);
                let value = Info_ValueForKey(cstr(&userinfo).as_ptr(), cstr(&key).as_ptr());
                let value_s = if !value.is_null() { cstr_to_str(value) } else { String::new() };

                if let Some(ref saber) = saber {
                    if !value_s.eq_ignore_ascii_case(saber) {
                        Info_SetValueForKey(
                            cstr(&userinfo).as_ptr() as *mut c_char,
                            cstr(&key).as_ptr(),
                            cstr(saber).as_ptr(),
                        );
                        trap::SetUserinfo(
                            ctx.engine,
                            mp_abi::game::syscalls::G_SET_USERINFO::GSetUserinfoArgs::new(
                                (*ent).s.number,
                                cstr(&userinfo),
                            ),
                        );
                    }
                }
                l += 1;
            }

            if (*client).saber[0].model[0] != 0 && (*client).saber[1].model[0] != 0 {
                // dual
                (*client).ps.fd.saberAnimLevelBase = SS_DUAL as c_int;
                (*client).ps.fd.saberAnimLevel = SS_DUAL as c_int;
                (*client).ps.fd.saberDrawAnimLevel = SS_DUAL as c_int;
            } else if (*client).saber[0].saberFlags & SFL_TWO_HANDED != 0 {
                // staff
                (*client).ps.fd.saberAnimLevel = SS_STAFF as c_int;
                (*client).ps.fd.saberDrawAnimLevel = SS_STAFF as c_int;
            } else {
                if (*client).sess.saberLevel < SS_FAST as c_int {
                    (*client).sess.saberLevel = SS_FAST as c_int;
                } else if (*client).sess.saberLevel > SS_STRONG as c_int {
                    (*client).sess.saberLevel = SS_STRONG as c_int;
                }
                (*client).ps.fd.saberAnimLevelBase = (*client).sess.saberLevel;
                (*client).ps.fd.saberAnimLevel = (*client).sess.saberLevel;
                (*client).ps.fd.saberDrawAnimLevel = (*client).sess.saberLevel;

                if (*ctx.world).cvars.g_gametype.integer != GT_SIEGE
                    && (*client).ps.fd.saberAnimLevel
                        > (*client).ps.fd.forcePowerLevel[FP_SABER_OFFENSE as usize]
                {
                    let lvl = (*client).ps.fd.forcePowerLevel[FP_SABER_OFFENSE as usize];
                    (*client).ps.fd.saberAnimLevelBase = lvl;
                    (*client).ps.fd.saberAnimLevel = lvl;
                    (*client).ps.fd.saberDrawAnimLevel = lvl;
                    (*client).sess.saberLevel = lvl;
                }
            }
            if (*ctx.world).cvars.g_gametype.integer != GT_SIEGE {
                // let's just make sure the styles we chose are cool
                if crate::bg_saberLoad::WP_SaberStyleValidForSaber(
                    &mut (*client).saber[0],
                    &mut (*client).saber[1],
                    (*client).ps.saberHolstered,
                    (*client).ps.fd.saberAnimLevel,
                ) == qfalse
                {
                    crate::bg_saberLoad::WP_UseFirstValidSaberStyle(
                        &mut (*client).saber[0],
                        &mut (*client).saber[1],
                        (*client).ps.saberHolstered,
                        &mut (*client).ps.fd.saberAnimLevel,
                    );
                    (*client).ps.fd.saberAnimLevelBase = (*client).ps.fd.saberAnimLevel;
                    (*client).saberCycleQueue = (*client).ps.fd.saberAnimLevel;
                }
            }
        }
        l = 0;

        if (*client).ps.fd.forceDoInit != 0 {
            // force a reread of force powers
            WP_InitForcePowers(ctx, ent);
            (*client).ps.fd.forceDoInit = 0;
        }

        if (*client).ps.fd.saberAnimLevel != SS_STAFF as c_int
            && (*client).ps.fd.saberAnimLevel != SS_DUAL as c_int
            && (*client).ps.fd.saberAnimLevel == (*client).ps.fd.saberDrawAnimLevel
            && (*client).ps.fd.saberAnimLevel == (*client).sess.saberLevel
        {
            if (*client).sess.saberLevel < SS_FAST as c_int {
                (*client).sess.saberLevel = SS_FAST as c_int;
            } else if (*client).sess.saberLevel > SS_STRONG as c_int {
                (*client).sess.saberLevel = SS_STRONG as c_int;
            }
            (*client).ps.fd.saberAnimLevel = (*client).sess.saberLevel;
            (*client).ps.fd.saberDrawAnimLevel = (*client).sess.saberLevel;

            if (*ctx.world).cvars.g_gametype.integer != GT_SIEGE
                && (*client).ps.fd.saberAnimLevel
                    > (*client).ps.fd.forcePowerLevel[FP_SABER_OFFENSE as usize]
            {
                let lvl = (*client).ps.fd.forcePowerLevel[FP_SABER_OFFENSE as usize];
                (*client).ps.fd.saberAnimLevel = lvl;
                (*client).ps.fd.saberDrawAnimLevel = lvl;
                (*client).sess.saberLevel = lvl;
            }
        }

        // find a spawn point — do it before setting health back up, so farthest
        // ranging doesn't count this client
        let mut spawn_origin: vec3_t = [0.0; 3];
        let mut spawn_angles: vec3_t = [0.0; 3];
        let spawn_point: *mut gentity_t;
        if (*client).sess.sessionTeam == TEAM_SPECTATOR {
            spawn_point = SelectSpectatorSpawnPoint(ctx, &mut spawn_origin, &mut spawn_angles);
        } else if (*ctx.world).cvars.g_gametype.integer == GT_CTF
            || (*ctx.world).cvars.g_gametype.integer == GT_CTY
        {
            spawn_point = SelectCTFSpawnPoint(
                ctx,
                (*client).sess.sessionTeam,
                (*client).pers.teamState.state as c_int,
                &mut spawn_origin,
                &mut spawn_angles,
            );
        } else if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE {
            spawn_point = SelectSiegeSpawnPoint(
                ctx,
                (*client).siegeClass,
                (*client).sess.sessionTeam,
                (*client).pers.teamState.state as c_int,
                &mut spawn_origin,
                &mut spawn_angles,
            );
        } else {
            let mut sp;
            loop {
                if (*ctx.world).cvars.g_gametype.integer == GT_POWERDUEL {
                    sp = SelectDuelSpawnPoint(
                        ctx,
                        (*client).sess.duelTeam,
                        (*client).ps.origin,
                        &mut spawn_origin,
                        &mut spawn_angles,
                    );
                } else if (*ctx.world).cvars.g_gametype.integer == GT_DUEL {
                    sp = SelectDuelSpawnPoint(
                        ctx,
                        DUELTEAM_SINGLE,
                        (*client).ps.origin,
                        &mut spawn_origin,
                        &mut spawn_angles,
                    );
                } else {
                    // the first spawn should be at a good looking spot
                    if (*client).pers.initialSpawn == qfalse && (*client).pers.localClient != qfalse {
                        (*client).pers.initialSpawn = qtrue;
                        sp = SelectInitialSpawnPoint(
                            ctx,
                            &mut spawn_origin,
                            &mut spawn_angles,
                            (*client).sess.sessionTeam,
                        );
                    } else {
                        // don't spawn near existing origin if possible
                        sp = SelectSpawnPoint(
                            ctx,
                            (*client).ps.origin,
                            &mut spawn_origin,
                            &mut spawn_angles,
                            (*client).sess.sessionTeam,
                        );
                    }
                }

                // Tim needs to prevent bots from spawning at the initial point on q3dm0...
                if (*sp).flags & FL_NO_BOTS != 0 && (*ent).r.svFlags & SVF_BOT != 0 {
                    continue; // try again
                }
                // just to be symmetric, we have a nohumans option...
                if (*sp).flags & FL_NO_HUMANS != 0 && (*ent).r.svFlags & SVF_BOT == 0 {
                    continue; // try again
                }

                break;
            }
            spawn_point = sp;
        }
        (*client).pers.teamState.state = crate::client::player_team_state::playerTeamStateState_t::TEAM_ACTIVE;

        // toggle the teleport bit so the client knows to not lerp and never clear the
        // voted flag
        let mut flags = (*client).ps.eFlags & EF_TELEPORT_BIT;
        flags ^= EF_TELEPORT_BIT;
        let game_flags = (*client).mGameFlags & ((PSG_VOTED | PSG_TEAMVOTED)) as u32;

        // clear everything but the persistant data
        let saved = (*client).pers;
        let saved_sess = (*client).sess;
        let saved_ping = (*client).ps.ping;
        let accuracy_hits = (*client).accuracy_hits;
        let accuracy_shots = (*client).accuracy_shots;
        let mut persistant: [c_int; MAX_PERSISTANT as usize] = [0; MAX_PERSISTANT as usize];
        let mut i = 0;
        while i < MAX_PERSISTANT {
            persistant[i as usize] = (*client).ps.persistant[i as usize];
            i += 1;
        }
        let event_sequence = (*client).ps.eventSequence;

        let saved_force = (*client).ps.fd;

        let save_saber_num = (*client).ps.saberEntityNum;

        let saved_siege_index = (*client).siegeClass;

        let mut saber_saved: [saberInfo_t; MAX_SABERS as usize] = (*client).saber;
        let mut g2_weapon_ptrs: [*mut c_void; MAX_SABERS as usize] = (*client).weaponGhoul2;

        i = 0;
        while i < crate::entity::hit_location::HL_MAX {
            (*ent).locationDamage[i as usize] = 0;
            i += 1;
        }

        core::ptr::write_bytes(client, 0, 1);
        (*client).bodyGrabIndex = ENTITYNUM_NONE;

        // Get the skin RGB based on his userinfo
        let value = Info_ValueForKey(cstr(&userinfo).as_ptr(), cstr("char_color_red").as_ptr());
        (*client).ps.customRGBA[0] = if !value.is_null() { cstr_to_str(value).parse().unwrap_or(0) } else { 255 };
        let value = Info_ValueForKey(cstr(&userinfo).as_ptr(), cstr("char_color_green").as_ptr());
        (*client).ps.customRGBA[1] = if !value.is_null() { cstr_to_str(value).parse().unwrap_or(0) } else { 255 };
        let value = Info_ValueForKey(cstr(&userinfo).as_ptr(), cstr("char_color_blue").as_ptr());
        (*client).ps.customRGBA[2] = if !value.is_null() { cstr_to_str(value).parse().unwrap_or(0) } else { 255 };

        if ((*client).ps.customRGBA[0] as c_int + (*client).ps.customRGBA[1] as c_int + (*client).ps.customRGBA[2] as c_int) < 100 {
            (*client).ps.customRGBA[0] = 255;
            (*client).ps.customRGBA[1] = 255;
            (*client).ps.customRGBA[2] = 255;
        }
        (*client).ps.customRGBA[3] = 255;

        (*client).siegeClass = saved_siege_index;

        (*client).saber = saber_saved;
        (*client).weaponGhoul2 = g2_weapon_ptrs;

        (*client).ps.saberEntityNum = save_saber_num;
        (*client).saberStoredIndex = save_saber_num;

        (*client).ps.fd = saved_force;

        (*client).ps.duelIndex = ENTITYNUM_NONE;

        // spawn with 100
        (*client).ps.jetpackFuel = 100;
        (*client).ps.cloakFuel = 100;

        (*client).pers = saved;
        (*client).sess = saved_sess;
        (*client).ps.ping = saved_ping;
        (*client).accuracy_hits = accuracy_hits;
        (*client).accuracy_shots = accuracy_shots;
        (*client).lastkilled_client = -1;

        i = 0;
        while i < MAX_PERSISTANT {
            (*client).ps.persistant[i as usize] = persistant[i as usize];
            i += 1;
        }
        (*client).ps.eventSequence = event_sequence;
        // increment the spawncount so the client will detect the respawn
        (*client).ps.persistant[PERS_SPAWN_COUNT as usize] += 1;
        (*client).ps.persistant[PERS_TEAM as usize] = (*client).sess.sessionTeam as c_int;

        (*client).airOutTime = (*ctx.world).level.time + 12000;

        // set max health
        let max_health;
        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE && (*client).siegeClass != -1 {
            let scl = &(*ctx.world).bg_state.bgSiegeClasses[(*client).siegeClass as usize];
            max_health = if scl.maxhealth != 0 { scl.maxhealth } else { 100 };
        } else {
            max_health = 100;
        }
        (*client).pers.maxHealth = max_health;
        if (*client).pers.maxHealth < 1 || (*client).pers.maxHealth > max_health {
            (*client).pers.maxHealth = 100;
        }
        (*client).ps.stats[STAT_MAX_HEALTH as usize] = (*client).pers.maxHealth;
        (*client).ps.eFlags = flags;
        (*client).mGameFlags = game_flags;

        (*ent).s.groundEntityNum = ENTITYNUM_NONE;
        (*ent).client = (*ctx.world).clients.as_mut_ptr().add(index as usize) as *mut c_void;
        (*ent).playerState = &mut (*((*ent).client as *mut gclient_t)).ps;
        (*ent).takedamage = qtrue;
        (*ent).inuse = qtrue;
        (*ent).classname = b"player\0".as_ptr() as *mut c_char;
        (*ent).r.contents = CONTENTS_BODY;
        (*ent).clipmask = MASK_PLAYERSOLID;
        (*ent).die = Some(EntDie::player_die);
        (*ent).waterlevel = 0;
        (*ent).watertype = 0;
        (*ent).flags = 0;

        crate::q_math::_VectorCopy(playerMins, &mut (*ent).r.mins);
        crate::q_math::_VectorCopy(playerMaxs, &mut (*ent).r.maxs);
        (*client).ps.crouchheight = CROUCH_MAXS_2;
        (*client).ps.standheight = DEFAULT_MAXS_2;

        (*client).ps.clientNum = index;
        // give default weapons
        (*client).ps.stats[STAT_WEAPONS as usize] = 1 << WP_NONE;

        let w_disable = if (*ctx.world).cvars.g_gametype.integer == GT_DUEL
            || (*ctx.world).cvars.g_gametype.integer == GT_POWERDUEL
        {
            (*ctx.world).cvars.g_duelWeaponDisable.integer
        } else {
            (*ctx.world).cvars.g_weaponDisable.integer
        };

        let mut in_siege_with_class = qfalse;

        if (*ctx.world).cvars.g_gametype.integer != GT_HOLOCRON
            && (*ctx.world).cvars.g_gametype.integer != GT_JEDIMASTER
            && HasSetSaberOnly(ctx) == qfalse
            && AllForceDisabled((*ctx.world).cvars.g_forcePowerDisable.integer) == qfalse
            && (*ctx.world).cvars.g_trueJedi.integer != 0
        {
            if (*ctx.world).cvars.g_gametype.integer >= GT_TEAM
                && ((*client).sess.sessionTeam == TEAM_BLUE || (*client).sess.sessionTeam == TEAM_RED)
            {
                if (*ctx.world).level.numPlayingClients > 0 {
                    let mut force_team = TEAM_SPECTATOR;
                    let mut i = 0;
                    while i < (*ctx.world).level.maxclients {
                        let cl = &(*ctx.world).clients[i as usize];
                        if cl.pers.connected == CON_DISCONNECTED as _ {
                            i += 1;
                            continue;
                        }
                        if cl.sess.sessionTeam == TEAM_BLUE || cl.sess.sessionTeam == TEAM_RED {
                            if WP_HasForcePowers(&cl.ps) != qfalse {
                                force_team = cl.sess.sessionTeam;
                            } else if cl.sess.sessionTeam == TEAM_BLUE {
                                force_team = TEAM_RED;
                            } else {
                                force_team = TEAM_BLUE;
                            }
                            break;
                        }
                        i += 1;
                    }
                    if WP_HasForcePowers(&(*client).ps) != qfalse && (*client).sess.sessionTeam != force_team {
                        let team_name = TeamName(force_team as c_int);
                        SetTeam(ctx, ent, team_name as *mut c_char);
                        return;
                    }
                }
            }

            if WP_HasForcePowers(&(*client).ps) != qfalse {
                (*client).ps.trueNonJedi = qfalse;
                (*client).ps.trueJedi = qtrue;
                (*client).ps.weapon = WP_SABER;
                (*client).ps.stats[STAT_WEAPONS as usize] = 1 << WP_SABER;
            } else {
                (*client).ps.trueNonJedi = qtrue;
                (*client).ps.trueJedi = qfalse;
                if w_disable == 0 || w_disable & (1 << WP_BRYAR_PISTOL) == 0 {
                    (*client).ps.stats[STAT_WEAPONS as usize] |= 1 << WP_BRYAR_PISTOL;
                }
                if w_disable == 0 || w_disable & (1 << WP_BLASTER) == 0 {
                    (*client).ps.stats[STAT_WEAPONS as usize] |= 1 << WP_BLASTER;
                }
                if w_disable == 0 || w_disable & (1 << WP_BOWCASTER) == 0 {
                    (*client).ps.stats[STAT_WEAPONS as usize] |= 1 << WP_BOWCASTER;
                }
                (*client).ps.stats[STAT_WEAPONS as usize] &= !(1 << WP_SABER);
                (*client).ps.stats[STAT_WEAPONS as usize] |= 1 << WP_MELEE;
                (*client).ps.ammo[AMMO_POWERCELL as usize] = ammoData[AMMO_POWERCELL as usize].max;
                (*client).ps.weapon = WP_BRYAR_PISTOL;
            }
        } else {
            // jediVmerc is incompatible with this gametype, turn it off!
            trap::Cvar_Set(
                ctx.engine,
                mp_abi::game::syscalls::G_CVAR_SET::GCvarSetArgs::new(
                    cstr("g_jediVmerc"),
                    cstr("0"),
                ),
            );
            if (*ctx.world).cvars.g_gametype.integer == GT_HOLOCRON {
                (*client).ps.stats[STAT_WEAPONS as usize] |= 1 << WP_SABER;
            } else if (*client).ps.fd.forcePowerLevel[FP_SABER_OFFENSE as usize] != 0 {
                (*client).ps.stats[STAT_WEAPONS as usize] |= 1 << WP_SABER;
            } else {
                (*client).ps.stats[STAT_WEAPONS as usize] |= 1 << WP_MELEE;
            }

            if (*ctx.world).cvars.g_gametype.integer != GT_SIEGE {
                if w_disable == 0 || w_disable & (1 << WP_BRYAR_PISTOL) == 0 {
                    (*client).ps.stats[STAT_WEAPONS as usize] |= 1 << WP_BRYAR_PISTOL;
                } else if (*ctx.world).cvars.g_gametype.integer == GT_JEDIMASTER {
                    (*client).ps.stats[STAT_WEAPONS as usize] |= 1 << WP_BRYAR_PISTOL;
                }
            }

            if (*ctx.world).cvars.g_gametype.integer == GT_JEDIMASTER {
                (*client).ps.stats[STAT_WEAPONS as usize] &= !(1 << WP_SABER);
                (*client).ps.stats[STAT_WEAPONS as usize] |= 1 << WP_MELEE;
            }

            if (*client).ps.stats[STAT_WEAPONS as usize] & (1 << WP_SABER) != 0 {
                (*client).ps.weapon = WP_SABER;
            } else if (*client).ps.stats[STAT_WEAPONS as usize] & (1 << WP_BRYAR_PISTOL) != 0 {
                (*client).ps.weapon = WP_BRYAR_PISTOL;
            } else {
                (*client).ps.weapon = WP_MELEE;
            }
        }

        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE
            && (*client).siegeClass != -1
            && (*client).sess.sessionTeam != TEAM_SPECTATOR
        {
            // well then, we will use a custom weaponset for our class
            let scl = &(*ctx.world).bg_state.bgSiegeClasses[(*client).siegeClass as usize];
            (*client).ps.stats[STAT_WEAPONS as usize] = scl.weapons;

            if (*client).ps.stats[STAT_WEAPONS as usize] & (1 << WP_SABER) != 0 {
                (*client).ps.weapon = WP_SABER;
            } else if (*client).ps.stats[STAT_WEAPONS as usize] & (1 << WP_BRYAR_PISTOL) != 0 {
                (*client).ps.weapon = WP_BRYAR_PISTOL;
            } else {
                (*client).ps.weapon = WP_MELEE;
            }
            in_siege_with_class = qtrue;

            let mut m = 0;
            while m < WP_NUM_WEAPONS {
                if (*client).ps.stats[STAT_WEAPONS as usize] & (1 << m) != 0 {
                    if (*client).ps.weapon != WP_SABER && m > (*client).ps.weapon {
                        // try to find the highest ranking weapon we have
                        (*client).ps.weapon = m;
                    }

                    if m >= WP_BRYAR_PISTOL {
                        // Max his ammo out for all the weapons he has.
                        let scl = &(*ctx.world).bg_state.bgSiegeClasses[(*client).siegeClass as usize];
                        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE && m == WP_ROCKET_LAUNCHER {
                            // don't give full ammo!
                            if scl.classflags & (1 << CFL_SINGLE_ROCKET as c_int) != 0 {
                                (*client).ps.ammo[weaponData[m as usize].ammoIndex as usize] = 1;
                            } else {
                                (*client).ps.ammo[weaponData[m as usize].ammoIndex as usize] = 10;
                            }
                        } else if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE
                            && scl.classflags & (1 << CFL_EXTRA_AMMO as c_int) != 0
                        {
                            // double ammo
                            (*client).ps.ammo[weaponData[m as usize].ammoIndex as usize] =
                                ammoData[weaponData[m as usize].ammoIndex as usize].max * 2;
                            (*client).ps.eFlags |= EF_DOUBLE_AMMO;
                        } else {
                            (*client).ps.ammo[weaponData[m as usize].ammoIndex as usize] =
                                ammoData[weaponData[m as usize].ammoIndex as usize].max;
                        }
                    }
                }
                m += 1;
            }
        }

        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE
            && (*client).siegeClass != -1
            && (*client).sess.sessionTeam != TEAM_SPECTATOR
        {
            let scl = &(*ctx.world).bg_state.bgSiegeClasses[(*client).siegeClass as usize];
            (*client).ps.stats[STAT_HOLDABLE_ITEMS as usize] = scl.invenItems;
            (*client).ps.stats[STAT_HOLDABLE_ITEM as usize] = 0;
        } else {
            (*client).ps.stats[STAT_HOLDABLE_ITEMS as usize] = 0;
            (*client).ps.stats[STAT_HOLDABLE_ITEM as usize] = 0;
        }

        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE
            && (*client).siegeClass != -1
            && (*ctx.world).bg_state.bgSiegeClasses[(*client).siegeClass as usize].powerups != 0
            && (*client).sess.sessionTeam != TEAM_SPECTATOR
        {
            let scl = &(*ctx.world).bg_state.bgSiegeClasses[(*client).siegeClass as usize];
            let mut i = 0;
            while i < PW_NUM_POWERUPS {
                if scl.powerups & (1 << i) != 0 {
                    (*client).ps.powerups[i as usize] = Q3_INFINITE;
                }
                i += 1;
            }
        }

        if (*client).sess.sessionTeam == TEAM_SPECTATOR {
            (*client).ps.stats[STAT_WEAPONS as usize] = 0;
            (*client).ps.stats[STAT_HOLDABLE_ITEMS as usize] = 0;
            (*client).ps.stats[STAT_HOLDABLE_ITEM as usize] = 0;
        }

        if in_siege_with_class == qfalse {
            (*client).ps.ammo[AMMO_BLASTER as usize] = 100;
        }

        (*client).ps.rocketLockIndex = ENTITYNUM_NONE;
        (*client).ps.rocketLockTime = 0;

        (*client).ps.genericEnemyIndex = -1;

        (*client).ps.isJediMaster = qfalse;

        if (*client).ps.fallingToDeath != 0 {
            (*client).ps.fallingToDeath = 0;
            (*client).noCorpse = qtrue;
        }

        // Do per-spawn force power initialization
        crate::w_force::WP_SpawnInitForcePowers(ctx, ent);

        // health will count down towards max_health
        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE
            && (*client).siegeClass != -1
            && (*ctx.world).bg_state.bgSiegeClasses[(*client).siegeClass as usize].starthealth != 0
        {
            let h = (*ctx.world).bg_state.bgSiegeClasses[(*client).siegeClass as usize].starthealth;
            (*ent).health = h;
            (*client).ps.stats[STAT_HEALTH as usize] = h;
        } else if (*ctx.world).cvars.g_gametype.integer == GT_DUEL
            || (*ctx.world).cvars.g_gametype.integer == GT_POWERDUEL
        {
            if (*ctx.world).cvars.g_gametype.integer == GT_POWERDUEL && (*client).sess.duelTeam == DUELTEAM_LONE {
                if (*ctx.world).cvars.g_duel_fraglimit.integer != 0 {
                    let h = ((*ctx.world).cvars.g_powerDuelStartHealth.integer as f32
                        - (((*ctx.world).cvars.g_powerDuelStartHealth.integer
                            - (*ctx.world).cvars.g_powerDuelEndHealth.integer) as f32
                            * (*client).sess.wins as f32
                            / (*ctx.world).cvars.g_duel_fraglimit.integer as f32))
                        as c_int;
                    (*ent).health = h;
                    (*client).ps.stats[STAT_HEALTH as usize] = h;
                    (*client).ps.stats[STAT_MAX_HEALTH as usize] = h;
                } else {
                    (*ent).health = 150;
                    (*client).ps.stats[STAT_HEALTH as usize] = 150;
                    (*client).ps.stats[STAT_MAX_HEALTH as usize] = 150;
                }
            } else {
                (*ent).health = 100;
                (*client).ps.stats[STAT_HEALTH as usize] = 100;
                (*client).ps.stats[STAT_MAX_HEALTH as usize] = 100;
            }
        } else if (*client).ps.stats[STAT_MAX_HEALTH as usize] <= 100 {
            let h = ((*client).ps.stats[STAT_MAX_HEALTH as usize] as f32 * 1.25) as c_int;
            (*ent).health = h;
            (*client).ps.stats[STAT_HEALTH as usize] = h;
        } else if (*client).ps.stats[STAT_MAX_HEALTH as usize] < 125 {
            (*ent).health = 125;
            (*client).ps.stats[STAT_HEALTH as usize] = 125;
        } else {
            let h = (*client).ps.stats[STAT_MAX_HEALTH as usize];
            (*ent).health = h;
            (*client).ps.stats[STAT_HEALTH as usize] = h;
        }

        // Start with a small amount of armor as well.
        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE && (*client).siegeClass != -1 {
            (*client).ps.stats[STAT_ARMOR as usize] =
                (*ctx.world).bg_state.bgSiegeClasses[(*client).siegeClass as usize].startarmor;
        } else if (*ctx.world).cvars.g_gametype.integer == GT_DUEL
            || (*ctx.world).cvars.g_gametype.integer == GT_POWERDUEL
        {
            (*client).ps.stats[STAT_ARMOR as usize] = 0;
        } else {
            (*client).ps.stats[STAT_ARMOR as usize] =
                ((*client).ps.stats[STAT_MAX_HEALTH as usize] as f32 * 0.25) as c_int;
        }

        crate::g_utils::G_SetOrigin(ent, spawn_origin);
        crate::q_math::_VectorCopy(spawn_origin, &mut (*client).ps.origin);

        // the respawned flag will be cleared after the attack and jump keys come up
        (*client).ps.pm_flags |= PMF_RESPAWNED;

        trap::GetUsercmd(
            ctx.engine,
            mp_abi::game::syscalls::G_GET_USERCMD::GGetUsercmdArgs::new(
                ent_id((*ctx.world).clients.as_ptr() as *const _, client as *const _),
                &mut (*client).pers.cmd,
            ),
        );
        SetClientViewAngle(ent, spawn_angles);

        if (*((*ent).client as *mut gclient_t)).sess.sessionTeam == TEAM_SPECTATOR {
            // (nothing)
        } else {
            crate::g_utils::G_KillBox(ctx, ent);
            trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));

            if (*client).ps.weapon <= WP_NONE {
                (*client).ps.weapon = WP_BRYAR_PISTOL;
            }

            (*client).ps.torsoTimer = 0;
            (*client).ps.legsTimer = 0;

            if (*client).ps.weapon == WP_SABER {
                G_SetAnim(
                    ent,
                    core::ptr::null_mut(),
                    SETANIM_BOTH,
                    (BOTH_STAND1TO2) as i32,
                    SETANIM_FLAG_OVERRIDE | SETANIM_FLAG_HOLD | SETANIM_FLAG_HOLDLESS,
                    0,
                );
            } else {
                G_SetAnim(
                    ent,
                    core::ptr::null_mut(),
                    SETANIM_TORSO,
                    (TORSO_RAISEWEAP1) as i32,
                    SETANIM_FLAG_OVERRIDE | SETANIM_FLAG_HOLD | SETANIM_FLAG_HOLDLESS,
                    0,
                );
                (*client).ps.legsAnim = WeaponReadyAnim[(*client).ps.weapon as usize];
            }
            (*client).ps.weaponstate = (WEAPON_RAISING) as i32;
            (*client).ps.weaponTime = (*client).ps.torsoTimer;
        }

        // don't allow full run speed for a bit
        (*client).ps.pm_flags |= PMF_TIME_KNOCKBACK;
        (*client).ps.pm_time = 100;

        (*client).respawnTime = (*ctx.world).level.time;
        (*client).inactivityTime =
            (*ctx.world).level.time + (*ctx.world).cvars.g_inactivity.integer * 1000;
        (*client).latched_buttons = 0;

        if (*ctx.world).level.intermissiontime != 0 {
            crate::g_main::MoveClientToIntermission(ctx, ent);
        } else {
            // fire the targets of the spawn point
            crate::g_utils::G_UseTargets(ctx, spawn_point, ent);
        }

        // set teams for NPCs to recognize
        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE {
            // Imperial (team1) team is allied with "enemy" NPCs in this mode
            if (*client).sess.sessionTeam == SIEGETEAM_TEAM1 {
                (*client).playerTeam = NPCTEAM_ENEMY;
                (*ent).s.teamowner = NPCTEAM_ENEMY as c_int;
                (*client).enemyTeam = NPCTEAM_PLAYER;
            } else {
                (*client).playerTeam = NPCTEAM_PLAYER;
                (*ent).s.teamowner = NPCTEAM_PLAYER as c_int;
                (*client).enemyTeam = NPCTEAM_ENEMY;
            }
        } else {
            (*client).playerTeam = NPCTEAM_PLAYER;
            (*ent).s.teamowner = NPCTEAM_PLAYER as c_int;
            (*client).enemyTeam = NPCTEAM_ENEMY;
        }

        // run a client frame to drop exactly to the floor, initialize animations and
        // other things
        (*client).ps.commandTime = (*ctx.world).level.time - 100;
        (*((*ent).client as *mut gclient_t)).pers.cmd.serverTime = (*ctx.world).level.time;
        crate::g_active::ClientThink(ctx, index, core::ptr::null_mut());

        // positively link the client, even if the command times are weird
        if (*((*ent).client as *mut gclient_t)).sess.sessionTeam != TEAM_SPECTATOR {
            BG_PlayerStateToEntityState(&mut (*client).ps, &mut (*ent).s, qtrue);
            crate::q_math::_VectorCopy((*((*ent).client as *mut gclient_t)).ps.origin, &mut (*ent).r.currentOrigin);
            trap::LinkEntity(ctx.engine, GLinkentityArgs::new(ent));
        }

        if (*ctx.world).cvars.g_spawnInvulnerability.integer != 0 {
            (*((*ent).client as *mut gclient_t)).ps.eFlags |= EF_INVULNERABLE;
            (*((*ent).client as *mut gclient_t)).invulnerableTimer =
                (*ctx.world).level.time + (*ctx.world).cvars.g_spawnInvulnerability.integer;
        }

        // run the presend to set anything else
        crate::g_active::ClientEndFrame(ctx, ent);

        // clear entity state values
        BG_PlayerStateToEntityState(&mut (*client).ps, &mut (*ent).s, qtrue);

        // rww - make sure client has a valid icarus instance
        trap::ICARUS_FreeEnt(
            ctx.engine,
            mp_abi::game::syscalls::G_ICARUS_FREEENT::GIcarusFreeentArgs::new(ent),
        );
        trap::ICARUS_InitEnt(
            ctx.engine,
            mp_abi::game::syscalls::G_ICARUS_INITENT::GIcarusInitentArgs::new(ent),
        );
    }
}

/// Raven `ClientDisconnect`.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:3816-3938`
// PORT-NOTE(multi-global-trap-g2): `trap_G2API_CleanGhoul2Models`/
// `trap_G2_HaveWeGhoul2Models`/`trap_SetConfigstring`/`trap_UnlinkEntity`,
// bot/log/follow teardown, reads `g_entities`/`g_gametype`, writes `level`.
pub fn ClientDisconnect(
    ctx: GameContext<'_>,clientNum: c_int) {
    use mp_abi::game::syscalls::G_G2_CLEANMODELS::GG2CleanmodelsArgs;
    use mp_abi::game::syscalls::G_G2_HAVEWEGHOULMODELS::GG2HaveweghoulmodelsArgs as GG2Haveweghoul2ModelsArgs;

    unsafe {
        // cleanup if we are kicking a bot that hasn't spawned yet
        G_RemoveQueuedBotBegin(ctx, clientNum);

        let ent = (*ctx.world).g_entities.as_mut_ptr().add(clientNum as usize);
        if (*ent).client.is_null() {
            return;
        }

        let mut i: c_int = 0;
        while i < (NUM_FORCE_POWERS) as i32 {
            if (*((*ent).client as *mut gclient_t)).ps.fd.forcePowersActive & (1 << i) != 0 {
                WP_ForcePowerStop(ctx, ent, i as forcePowers_t);
            }
            i += 1;
        }

        i = (TRACK_CHANNEL_1) as i32;
        while i < (NUM_TRACK_CHANNELS) as i32 {
            let idx = (i - 50) as usize;
            if (*((*ent).client as *mut gclient_t)).ps.fd.killSoundEntIndex[idx] != 0
                && (*((*ent).client as *mut gclient_t)).ps.fd.killSoundEntIndex[idx] < MAX_GENTITIES as c_int
                && (*((*ent).client as *mut gclient_t)).ps.fd.killSoundEntIndex[idx] > 0
            {
                G_MuteSound(ctx, (*((*ent).client as *mut gclient_t)).ps.fd.killSoundEntIndex[idx], CHAN_VOICE);
            }
            i += 1;
        }

        if (*((*ent).client as *mut gclient_t)).ps.m_iVehicleNum != 0 {
            // tell it I'm getting off
            let veh = (*ctx.world)
                .g_entities
                .as_mut_ptr()
                .add((*((*ent).client as *mut gclient_t)).ps.m_iVehicleNum as usize);

            if (*veh).inuse != qfalse && !(*veh).client.is_null() && !(*veh).m_pVehicle.is_null() {
                // PORT-NOTE(vehicle-eject-unported): m_pVehicleInfo->Eject is a C++
                // vtable call not yet ported; the connected-flag dance around it is
                // transcribed faithfully but the call itself cannot be made yet.
                let p_con = (*((*ent).client as *mut gclient_t)).pers.connected;
                (*((*ent).client as *mut gclient_t)).pers.connected = CON_DISCONNECTED as _;
                //TODO: Port m_pVehicleInfo->Eject
                // Source: oracle/oracle/codemp/game/g_client.c:3862
                (*((*ent).client as *mut gclient_t)).pers.connected = p_con;
            }
        }

        // stop any following clients
        i = 0;
        while i < (*ctx.world).level.maxclients {
            let cl = &(*ctx.world).clients[i as usize];
            if cl.sess.sessionTeam == TEAM_SPECTATOR
                && cl.sess.spectatorState == crate::client::spectator_state::spectatorState_t::SPECTATOR_FOLLOW
                && cl.sess.spectatorClient == clientNum
            {
                StopFollowing(ctx, (*ctx.world).g_entities.as_mut_ptr().add(i as usize));
            }
            i += 1;
        }

        // send effect if they were completely connected
        if (*((*ent).client as *mut gclient_t)).pers.connected == CON_CONNECTED as _
            && (*((*ent).client as *mut gclient_t)).sess.sessionTeam != TEAM_SPECTATOR
        {
            let tent = G_TempEntity(ctx, (*((*ent).client as *mut gclient_t)).ps.origin, (EV_PLAYER_TELEPORT_OUT) as i32);
            (*tent).s.clientNum = (*ent).s.clientNum;

            // They don't get to take powerups with them!
            // Especially important for stuff like CTF flags
            TossClientItems(ctx, ent);
        }

        G_LogPrintf(ctx, cstr(&format!("ClientDisconnect: {}\n", clientNum)).as_ptr());
        G_LogPrintf(
            ctx,
            cstr(&format!(
                "{} disconnected with IP: {}\n",
                cstr_to_str((*((*ent).client as *mut gclient_t)).pers.netname.as_ptr()),
                cstr_to_str((*((*ent).client as *mut gclient_t)).sess.IPstring.as_ptr()),
            ))
            .as_ptr(),
        );

        // if we are playing in tourney mode, give a win to the other player and clear his
        // frags for this round
        if (*ctx.world).cvars.g_gametype.integer == GT_DUEL
            && (*ctx.world).level.intermissiontime == 0
            && (*ctx.world).level.warmupTime == 0
        {
            if (*ctx.world).level.sortedClients[1] == clientNum {
                let idx0 = (*ctx.world).level.sortedClients[0] as usize;
                (*ctx.world).clients[idx0].ps.persistant[PERS_SCORE as usize] = 0;
                (*ctx.world).clients[idx0].sess.wins += 1;
                ClientUserinfoChanged(ctx, (*ctx.world).level.sortedClients[0]);
            } else if (*ctx.world).level.sortedClients[0] == clientNum {
                let idx1 = (*ctx.world).level.sortedClients[1] as usize;
                (*ctx.world).clients[idx1].ps.persistant[PERS_SCORE as usize] = 0;
                (*ctx.world).clients[idx1].sess.wins += 1;
                ClientUserinfoChanged(ctx, (*ctx.world).level.sortedClients[1]);
            }
        }

        if !(*ent).ghoul2.is_null()
            && trap::G2_HaveWeGhoul2Models(
                ctx.engine,
                GG2Haveweghoul2ModelsArgs::new((*ent).ghoul2),
            ) != qfalse
        {
            trap::G2API_CleanGhoul2Models(
                ctx.engine,
                GG2CleanmodelsArgs::new(&mut (*ent).ghoul2 as *mut *mut c_void),
            );
        }
        i = 0;
        while i < (MAX_SABERS) as i32 {
            let idx = i as usize;
            if !(*((*ent).client as *mut gclient_t)).weaponGhoul2[idx].is_null()
                && trap::G2_HaveWeGhoul2Models(
                    ctx.engine,
                    GG2Haveweghoul2ModelsArgs::new((*((*ent).client as *mut gclient_t)).weaponGhoul2[idx]),
                ) != qfalse
            {
                trap::G2API_CleanGhoul2Models(
                    ctx.engine,
                    GG2CleanmodelsArgs::new(
                        &mut (*((*ent).client as *mut gclient_t)).weaponGhoul2[idx] as *mut *mut c_void,
                    ),
                );
            }
            i += 1;
        }

        trap::UnlinkEntity(ctx.engine, GUnlinkentityArgs::new(ent));
        (*ent).s.modelindex = 0;
        (*ent).inuse = qfalse;
        (*ent).classname = b"disconnected\0".as_ptr() as *mut c_char;
        (*((*ent).client as *mut gclient_t)).pers.connected = CON_DISCONNECTED as _;
        (*((*ent).client as *mut gclient_t)).ps.persistant[PERS_TEAM as usize] = TEAM_FREE as c_int;
        (*((*ent).client as *mut gclient_t)).sess.sessionTeam = TEAM_FREE;
        (*ent).r.contents = 0;

        trap::SetConfigstring(
            ctx.engine,
            GSetConfigstringArgs::new(CS_PLAYERS + clientNum, cstr("")),
        );

        CalculateRanks(ctx);

        if (*ent).r.svFlags & SVF_BOT != 0 {
            BotAIShutdownClient(ctx, clientNum, qfalse);
        }

        G_ClearClientLog(ctx, clientNum);
    }
}

/// Raven `SetupGameGhoul2Model`.
///
/// There are two ghoul2 model instances per player (actually three). One is on
/// the clientinfo (the base for the client side player, and copied for player
/// spawns and for corpses). One is attached to the centity itself, which is the
/// model actually animated and rendered by the system. The final is the game
/// ghoul2 model. This is animated by pmove on the server, and is used for
/// determining where the lightsaber should be, and for per-poly collision tests.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:1519-1861`
pub fn SetupGameGhoul2Model(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    modelname: *mut c_char,
    skinName: *mut c_char,
) {
    use mp_abi::game::syscalls::G_G2_INITGHOUL2MODEL::GG2Initghoul2ModelArgs as GG2InitghoulModelArgs;
    use mp_abi::game::syscalls::G_G2_ADDBOLT::GG2AddboltArgs as GG2AddBoltArgs;
    use mp_abi::game::syscalls::G_G2_PLAYANIM::GG2PlayanimArgs as GG2SetBoneAnimArgs;
    use mp_abi::game::syscalls::G_G2_ANGLEOVERRIDE::GG2AngleoverrideArgs as GG2SetBoneAnglesArgs;
    use mp_abi::game::syscalls::G_G2_SETSKIN::GG2SetskinArgs as GG2SetSkinArgs;
    use mp_abi::game::syscalls::G_G2_GETGLANAME::GG2GetglanameArgs as GG2GetGLANameArgs;
    use mp_abi::game::syscalls::G_G2_CLEANMODELS::GG2CleanmodelsArgs;
    use mp_abi::game::syscalls::G_G2_DUPLICATEGHOUL2INSTANCE::GG2Duplicateghoul2InstanceArgs as GG2DuplicateGhoul2InstanceArgs;
    use mp_abi::game::syscalls::G_G2_ATTACHINSTANCETOENTNUM::GG2AttachinstancetoentnumArgs as GG2AttachInstanceToEntNumArgs;
    use mp_abi::game::syscalls::G_G2_COPYSPECIFICGHOUL2MODEL::GG2Copyspecificghoul2ModelArgs as GG2CopySpecificGhoul2ModelArgs;
    use mp_abi::game::syscalls::G_G2_SETBOLTINFO::GG2SetboltinfoArgs as GG2SetBoltInfoArgs;
    use mp_abi::game::syscalls::G_G2_HAVEWEGHOULMODELS::GG2HaveweghoulmodelsArgs as GG2Haveweghoul2ModelsArgs;

    unsafe {
        let mut handle: c_int = 0;
        let mut afilename: [c_char; 260] = [0; 260]; // MAX_QPATH
        let mut GLAName: [c_char; 260] = [0; 260];
        let mut tempVec: vec3_t = [0.0; 3];

        // First things first. If this is a ghoul2 model, then let's make sure we demolish this first.
        if !(*ent).ghoul2.is_null()
            && trap::G2_HaveWeGhoul2Models(
                ctx.engine,
                GG2Haveweghoul2ModelsArgs::new((*ent).ghoul2),
            ) != qfalse
        {
            trap::G2API_CleanGhoul2Models(
                ctx.engine,
                GG2CleanmodelsArgs::new(&mut (*ent).ghoul2 as *mut *mut c_void),
            );
        }

        // rww - just load the "standard" model for the server
        if (*ctx.world).globals.precachedKyle.is_null() {
            let mut defSkin: c_int = 0;

            write_cstr_field(&mut afilename, "models/players/kyle/model.glm");
            handle = trap::G2API_InitGhoul2Model(
                ctx.engine,
                GG2InitghoulModelArgs::new(
                    &mut (*ctx.world).globals.precachedKyle as *mut *mut c_void,
                    cstr(&cstr_to_str(afilename.as_ptr())),
                    0,
                    0,
                    -20,
                    0,
                    0,
                ),
            );

            if handle < 0 {
                return;
            }

            defSkin = trap::R_RegisterSkin(
                ctx.engine,
                mp_abi::game::syscalls::G_R_REGISTERSKIN::GRRegisterskinArgs::new(
                    cstr("models/players/kyle/model_default.skin"),
                ),
            );
            trap::G2API_SetSkin(
                ctx.engine,
                GG2SetSkinArgs::new((*ctx.world).globals.precachedKyle, 0, defSkin, defSkin),
            );
        }

        if !(*ctx.world).globals.precachedKyle.is_null()
            && trap::G2_HaveWeGhoul2Models(
                ctx.engine,
                GG2Haveweghoul2ModelsArgs::new((*ctx.world).globals.precachedKyle),
            ) != qfalse
        {
            if (*ctx.world).cvars.d_perPlayerGhoul2.integer != 0
                || (*ent).s.number >= (MAX_CLIENTS) as i32
                || G_PlayerHasCustomSkeleton(ent) != qfalse
            {
                // rww - allow option for perplayer models on server for collision and bolt stuff.
                let mut modelFullPath: [c_char; 260] = [0; 260];
                let mut truncModelName: [c_char; 260] = [0; 260];
                let mut skin: [c_char; 260] = [0; 260];
                let mut vehicleName: [c_char; 260] = [0; 260];
                let mut skinHandle: c_int = 0;
                let mut i: c_int = 0;
                let mut p: *mut c_char = core::ptr::null_mut();

                // If this is a vehicle, get its model name.
                // PORT-NOTE(vehicle-pointer-overlay): ruling 14 uses the bgEntity_t -> *mut gentity_t
                // overlay pattern; m_pVehicle is accessed safely through the overlay cast in this context.
                if !(*ent).client.is_null() && (*((*ent).client as *mut gclient_t)).NPC_class == CLASS_VEHICLE {
                    write_cstr_field(&mut vehicleName, cstr_to_str(modelname));
                    BG_GetVehicleModelName(modelname, &mut (*ctx.world).bg_state);
                    write_cstr_field(&mut truncModelName, cstr_to_str(modelname));
                    skin[0] = 0;
                    if !(*ent).m_pVehicle.is_null()
                        && !(*((*ent).m_pVehicle as *mut Vehicle_t)).m_pVehicleInfo.is_null()
                        && !(*(*((*ent).m_pVehicle as *mut Vehicle_t)).m_pVehicleInfo).skin.is_null()
                        && *(*(*((*ent).m_pVehicle as *mut Vehicle_t)).m_pVehicleInfo).skin as c_int != 0
                    {
                        let skin_str = format!(
                            "models/players/{}/model_{}.skin",
                            cstr_to_str(modelname),
                            cstr_to_str(
                                (*(*((*ent).m_pVehicle as *mut Vehicle_t)).m_pVehicleInfo).skin
                            )
                        );
                        skinHandle = trap::R_RegisterSkin(
                            ctx.engine,
                            mp_abi::game::syscalls::G_R_REGISTERSKIN::GRRegisterskinArgs::new(
                                cstr(&skin_str),
                            ),
                        );
                    } else {
                        let skin_str = format!("models/players/{}/model_default.skin", cstr_to_str(modelname));
                        skinHandle = trap::R_RegisterSkin(
                            ctx.engine,
                            mp_abi::game::syscalls::G_R_REGISTERSKIN::GRRegisterskinArgs::new(
                                cstr(&skin_str),
                            ),
                        );
                    }
                } else {
                    if !skinName.is_null() && *skinName as c_int != 0 {
                        write_cstr_field(&mut skin, cstr_to_str(skinName));
                        write_cstr_field(&mut truncModelName, cstr_to_str(modelname));
                    } else {
                        write_cstr_field(&mut skin, "default");
                        write_cstr_field(&mut truncModelName, cstr_to_str(modelname));
                        p = crate::q_shared::Q_strrchr(truncModelName.as_ptr(), '/' as c_int);

                        if !p.is_null() {
                            *p = 0;
                            p = p.add(1);

                            while !p.is_null() && *p as c_int != 0 {
                                skin[i as usize] = *p;
                                i += 1;
                                p = p.add(1);
                            }
                            skin[i as usize] = 0;
                            i = 0;
                        }

                        if BG_IsValidCharacterModel(truncModelName.as_ptr(), skin.as_ptr()) == qfalse
                        {
                            write_cstr_field(&mut truncModelName, "kyle");
                            write_cstr_field(&mut skin, "default");
                        }

                        if (*ctx.world).cvars.g_gametype.integer >= GT_TEAM
                            && (*ctx.world).cvars.g_gametype.integer != GT_SIEGE
                            && (*ctx.world).cvars.g_trueJedi.integer == 0
                        {
                            BG_ValidateSkinForTeam(
                                truncModelName.as_ptr(),
                                skin.as_mut_ptr(),
                                (*((*ent).client as *mut gclient_t)).sess.sessionTeam,
                                core::ptr::null_mut(),
                            );
                        } else if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE {
                            // force skin for class if appropriate
                            if (*((*ent).client as *mut gclient_t)).siegeClass != -1 {
                                let scl = &(*ctx.world)
                                    .bg_state
                                    .bgSiegeClasses[(*((*ent).client as *mut gclient_t)).siegeClass as usize];
                                if scl.forcedSkin[0] as c_int != 0 {
                                    write_cstr_field(&mut skin, cstr_to_str(scl.forcedSkin.as_ptr()));
                                }
                            }
                        }
                    }
                }

                if skin[0] as c_int != 0 {
                    let useSkinName = if crate::q_shared::Q_strchr(skin.as_ptr(), '|' as c_int)
                        .is_null()
                        == false
                    {
                        // three part skin
                        format!(
                            "models/players/{}/|{}",
                            cstr_to_str(truncModelName.as_ptr()),
                            cstr_to_str(skin.as_ptr())
                        )
                    } else {
                        format!(
                            "models/players/{}/model_{}.skin",
                            cstr_to_str(truncModelName.as_ptr()),
                            cstr_to_str(skin.as_ptr())
                        )
                    };

                    skinHandle = trap::R_RegisterSkin(
                        ctx.engine,
                        mp_abi::game::syscalls::G_R_REGISTERSKIN::GRRegisterskinArgs::new(
                            cstr(&useSkinName),
                        ),
                    );
                }

                write_cstr_field(
                    &mut modelFullPath,
                    &format!(
                        "models/players/{}/model.glm",
                        cstr_to_str(truncModelName.as_ptr())
                    ),
                );
                handle = trap::G2API_InitGhoul2Model(
                    ctx.engine,
                    GG2InitghoulModelArgs::new(
                        &mut (*ent).ghoul2 as *mut *mut c_void,
                        cstr(&cstr_to_str(modelFullPath.as_ptr())),
                        0,
                        skinHandle,
                        -20,
                        0,
                        0,
                    ),
                );

                if handle < 0 {
                    // Huh. Guess we don't have this model. Use the default.
                    if !(*ent).ghoul2.is_null()
                        && trap::G2_HaveWeGhoul2Models(
                            ctx.engine,
                            GG2Haveweghoul2ModelsArgs::new((*ent).ghoul2),
                        ) != qfalse
                    {
                        trap::G2API_CleanGhoul2Models(
                            ctx.engine,
                            GG2CleanmodelsArgs::new(&mut (*ent).ghoul2 as *mut *mut c_void),
                        );
                    }
                    (*ent).ghoul2 = core::ptr::null_mut();
                    trap::G2API_DuplicateGhoul2Instance(
                        ctx.engine,
                        GG2DuplicateGhoul2InstanceArgs::new(
                            (*ctx.world).globals.precachedKyle,
                            &mut (*ent).ghoul2 as *mut *mut c_void,
                        ),
                    );
                } else {
                    trap::G2API_SetSkin(
                        ctx.engine,
                        GG2SetSkinArgs::new((*ent).ghoul2, 0, skinHandle, skinHandle),
                    );

                    GLAName[0] = 0;
                    trap::G2API_GetGLAName(
                        ctx.engine,
                        GG2GetGLANameArgs::new((*ent).ghoul2, 0, GLAName.as_mut_ptr()),
                    );

                    if GLAName[0] as c_int == 0
                        || crate::q_shared::Q_strstr(
                            GLAName.as_ptr(),
                            b"players/_humanoid/\0".as_ptr() as *const c_char,
                        )
                        .is_null()
                            && (*ent).s.number < (MAX_CLIENTS) as i32
                            && G_PlayerHasCustomSkeleton(ent) == qfalse
                    {
                        // a bad model
                        trap::G2API_CleanGhoul2Models(
                            ctx.engine,
                            GG2CleanmodelsArgs::new(&mut (*ent).ghoul2 as *mut *mut c_void),
                        );
                        (*ent).ghoul2 = core::ptr::null_mut();
                        trap::G2API_DuplicateGhoul2Instance(
                            ctx.engine,
                            GG2DuplicateGhoul2InstanceArgs::new(
                                (*ctx.world).globals.precachedKyle,
                                &mut (*ent).ghoul2 as *mut *mut c_void,
                            ),
                        );
                    }

                    if (*ent).s.number >= (MAX_CLIENTS) as i32 {
                        (*ent).s.modelGhoul2 = 1; // so we know to free it on the client when we're removed.

                        if skin[0] as c_int != 0 {
                            // append it after a *
                            let tail_str = format!(
                                "{}*{}",
                                cstr_to_str(modelFullPath.as_ptr()),
                                cstr_to_str(skin.as_ptr())
                            );
                            write_cstr_field(&mut modelFullPath, &tail_str);
                        }

                        if !(*ent).client.is_null() && (*((*ent).client as *mut gclient_t)).NPC_class == CLASS_VEHICLE {
                            // vehicles are tricky and send over their vehicle names as the model
                            (*ent).s.modelindex = G_ModelIndex(vehicleName.as_ptr());
                        } else {
                            (*ent).s.modelindex = G_ModelIndex(modelFullPath.as_ptr());
                        }
                    }
                }
            } else {
                trap::G2API_DuplicateGhoul2Instance(
                    ctx.engine,
                    GG2DuplicateGhoul2InstanceArgs::new(
                        (*ctx.world).globals.precachedKyle,
                        &mut (*ent).ghoul2 as *mut *mut c_void,
                    ),
                );
            }
        } else {
            return;
        }

        // Attach the instance to this entity num so we can make use of client-server
        // shared operations if possible.
        trap::G2API_AttachInstanceToEntNum(
            ctx.engine,
            GG2AttachInstanceToEntNumArgs::new((*ent).ghoul2, (*ent).s.number, qtrue),
        );

        // The model is now loaded.
        GLAName[0] = 0;

        if (*ctx.world).bg_state.BGPAFtextLoaded == qfalse {
            if crate::bg_panimate::BG_ParseAnimationFile(
                cstr("models/players/_humanoid/animation.cfg").as_ptr(),
                (*ctx.world).bg_state.bgHumanoidAnimations.as_mut_ptr(),
                qtrue,
            ) == -1
            {
                crate::g_main::Com_Printf(
                    cstr("Failed to load humanoid animation file\n").as_ptr(),
                );
                return;
            }
        }

        if (*ent).s.number >= (MAX_CLIENTS) as i32 || G_PlayerHasCustomSkeleton(ent) != qfalse {
            (*ent).localAnimIndex = -1;

            GLAName[0] = 0;
            trap::G2API_GetGLAName(
                ctx.engine,
                GG2GetGLANameArgs::new((*ent).ghoul2, 0, GLAName.as_mut_ptr()),
            );

            if GLAName[0] as c_int != 0
                && crate::q_shared::Q_strstr(
                    GLAName.as_ptr(),
                    b"players/_humanoid/\0".as_ptr() as *const c_char,
                )
                .is_null()
            {
                // it doesn't use humanoid anims.
                let slash = crate::q_shared::Q_strrchr(GLAName.as_ptr(), '/' as c_int);
                if !slash.is_null() {
                    write_cstr_field(&mut GLAName, "/animation.cfg");

                    (*ent).localAnimIndex = crate::bg_panimate::BG_ParseAnimationFile(
                        GLAName.as_ptr(),
                        core::ptr::null_mut(),
                        qfalse,
                    );
                }
            } else {
                // humanoid index.
                if !crate::q_shared::Q_strstr(
                    GLAName.as_ptr(),
                    b"players/rockettrooper/\0".as_ptr() as *const c_char,
                )
                .is_null()
                {
                    (*ent).localAnimIndex = 1;
                } else {
                    (*ent).localAnimIndex = 0;
                }
            }

            if (*ent).localAnimIndex == -1 {
                crate::g_main::Com_Error((ERR_DROP) as i32, cstr("NPC had an invalid GLA\n").as_ptr());
            }
        } else {
            GLAName[0] = 0;
            trap::G2API_GetGLAName(
                ctx.engine,
                GG2GetGLANameArgs::new((*ent).ghoul2, 0, GLAName.as_mut_ptr()),
            );

            if !crate::q_shared::Q_strstr(
                GLAName.as_ptr(),
                b"players/rockettrooper/\0".as_ptr() as *const c_char,
            )
            .is_null()
            {
                // assert(!"Should not have gotten in here with rockettrooper skel");
                (*ent).localAnimIndex = 1;
            } else {
                (*ent).localAnimIndex = 0;
            }
        }

        if (*ent).s.NPC_class == (CLASS_VEHICLE) as i32 && !(*ent).m_pVehicle.is_null() {
            // do special vehicle stuff
            let mut strTemp: [c_char; 128] = [0; 128];
            let mut i: c_int = 0;

            // Setup the default first bolt
            i = trap::G2API_AddBolt(
                ctx.engine,
                GG2AddBoltArgs::new((*ent).ghoul2, 0, cstr("model_root")),
            );

            // Setup the droid unit.
            (*((*ent).m_pVehicle as *mut Vehicle_t)).m_iDroidUnitTag = trap::G2API_AddBolt(
                ctx.engine,
                GG2AddBoltArgs::new((*ent).ghoul2, 0, cstr("*droidunit")),
            );

            // Setup the Exhausts.
            i = 0;
            while i < (MAX_VEHICLE_EXHAUSTS) as i32 {
                write_cstr_field(&mut strTemp, &format!("*exhaust{}", i + 1));
                (*((*ent).m_pVehicle as *mut Vehicle_t)).m_iExhaustTag[i as usize] = trap::G2API_AddBolt(
                    ctx.engine,
                    GG2AddBoltArgs::new((*ent).ghoul2, 0, cstr(&cstr_to_str(strTemp.as_ptr()))),
                );
                i += 1;
            }

            // Setup the Muzzles.
            i = 0;
            while i < (MAX_VEHICLE_MUZZLES) as i32 {
                write_cstr_field(&mut strTemp, &format!("*muzzle{}", i + 1));
                (*((*ent).m_pVehicle as *mut Vehicle_t)).m_iMuzzleTag[i as usize] = trap::G2API_AddBolt(
                    ctx.engine,
                    GG2AddBoltArgs::new((*ent).ghoul2, 0, cstr(&cstr_to_str(strTemp.as_ptr()))),
                );
                if (*((*ent).m_pVehicle as *mut Vehicle_t)).m_iMuzzleTag[i as usize] == -1 {
                    // ergh, try *flash?
                    write_cstr_field(&mut strTemp, &format!("*flash{}", i + 1));
                    (*((*ent).m_pVehicle as *mut Vehicle_t)).m_iMuzzleTag[i as usize] = trap::G2API_AddBolt(
                        ctx.engine,
                        GG2AddBoltArgs::new((*ent).ghoul2, 0, cstr(&cstr_to_str(strTemp.as_ptr()))),
                    );
                }
                i += 1;
            }

            // Setup the Turrets.
            i = 0;
            while i < (MAX_VEHICLE_TURRET_MUZZLES) as i32 {
                if !(*(*((*ent).m_pVehicle as *mut Vehicle_t)).m_pVehicleInfo).turret[i as usize]
                    .gunnerViewTag
                    .is_null()
                {
                    (*((*ent).m_pVehicle as *mut Vehicle_t)).m_iGunnerViewTag[i as usize] = trap::G2API_AddBolt(
                        ctx.engine,
                        GG2AddBoltArgs::new(
                            (*ent).ghoul2,
                            0,
                            cstr(&cstr_to_str(
                                (*(*((*ent).m_pVehicle as *mut Vehicle_t)).m_pVehicleInfo).turret[i as usize]
                                    .gunnerViewTag,
                            )),
                        ),
                    );
                } else {
                    (*((*ent).m_pVehicle as *mut Vehicle_t)).m_iGunnerViewTag[i as usize] = -1;
                }
                i += 1;
            }
        }

        if !(*ent).client.is_null()
            && ((*((*ent).client as *mut gclient_t)).ps.weapon == WP_SABER || (*ent).s.number < (MAX_CLIENTS) as i32)
        {
            // a player or NPC saber user
            trap::G2API_AddBolt(
                ctx.engine,
                GG2AddBoltArgs::new((*ent).ghoul2, 0, cstr("*r_hand")),
            );
            trap::G2API_AddBolt(
                ctx.engine,
                GG2AddBoltArgs::new((*ent).ghoul2, 0, cstr("*l_hand")),
            );

            // rhand must always be first bolt. lhand always second. Whichever you want the
            // jetpack bolted to must always be third.
            trap::G2API_AddBolt(
                ctx.engine,
                GG2AddBoltArgs::new((*ent).ghoul2, 0, cstr("*chestg")),
            );

            // claw bolts
            trap::G2API_AddBolt(
                ctx.engine,
                GG2AddBoltArgs::new((*ent).ghoul2, 0, cstr("*r_hand_cap_r_arm")),
            );
            trap::G2API_AddBolt(
                ctx.engine,
                GG2AddBoltArgs::new((*ent).ghoul2, 0, cstr("*l_hand_cap_l_arm")),
            );

            trap::G2API_SetBoneAnim(
                ctx.engine,
                GG2SetBoneAnimArgs::new(
                    (*ent).ghoul2,
                    0,
                    cstr("model_root").as_ptr(),
                    0,
                    12,
                    BONE_ANIM_OVERRIDE_LOOP,
                    1.0f32,
                    (*ctx.world).level.time,
                    -1.0,
                    -1,
                ),
            );
            trap::G2API_SetBoneAngles(
                ctx.engine,
                GG2SetBoneAnglesArgs::new(
                    (*ent).ghoul2,
                    0,
                    cstr("upper_lumbar"),
                    &tempVec as *const vec3_t,
                    BONE_ANGLES_POSTMULT,
                    POSITIVE_X as c_int,
                    NEGATIVE_Y as c_int,
                    NEGATIVE_Z as c_int,
                    core::ptr::null_mut(),
                    0,
                    (*ctx.world).level.time,
                ),
            );
            trap::G2API_SetBoneAngles(
                ctx.engine,
                GG2SetBoneAnglesArgs::new(
                    (*ent).ghoul2,
                    0,
                    cstr("cranium"),
                    &tempVec as *const vec3_t,
                    BONE_ANGLES_POSTMULT,
                    POSITIVE_Z as c_int,
                    NEGATIVE_Y as c_int,
                    POSITIVE_X as c_int,
                    core::ptr::null_mut(),
                    0,
                    (*ctx.world).level.time,
                ),
            );

            if (*ctx.world).globals.g2SaberInstance.is_null() {
                trap::G2API_InitGhoul2Model(
                    ctx.engine,
                    GG2InitghoulModelArgs::new(
                        &mut (*ctx.world).globals.g2SaberInstance as *mut *mut c_void,
                        cstr("models/weapons2/saber/saber_w.glm"),
                        0,
                        0,
                        -20,
                        0,
                        0,
                    ),
                );

                if !(*ctx.world).globals.g2SaberInstance.is_null() {
                    // indicate we will be bolted to model 0 (ie the player) on bolt 0
                    // (always the right hand) when we get copied
                    trap::G2API_SetBoltInfo(
                        ctx.engine,
                        GG2SetBoltInfoArgs::new((*ctx.world).globals.g2SaberInstance, 0, 0),
                    );
                    // now set up the gun bolt on it
                    trap::G2API_AddBolt(
                        ctx.engine,
                        GG2AddBoltArgs::new(
                            (*ctx.world).globals.g2SaberInstance,
                            0,
                            cstr("*blade1"),
                        ),
                    );
                }
            }

            if G_SaberModelSetup(ctx, ent) != qfalse {
                if !(*ctx.world).globals.g2SaberInstance.is_null() {
                    trap::G2API_CopySpecificGhoul2Model(
                        ctx.engine,
                        GG2CopySpecificGhoul2ModelArgs::new(
                            (*ctx.world).globals.g2SaberInstance,
                            0,
                            (*ent).ghoul2,
                            1,
                        ),
                    );
                }
            }
        }

        if (*ent).s.number >= (MAX_CLIENTS) as i32 {
            // some extra NPC stuff
            if trap::G2API_AddBolt(
                ctx.engine,
                GG2AddBoltArgs::new((*ent).ghoul2, 0, cstr("lower_lumbar")),
            ) == -1
            {
                // check now to see if we have this bone for setting anims and such
                (*ent).noLumbar = qtrue;
            }
        }
    }
}

/// Raven `ClientUserinfoChanged`.
///
/// Source: `oracle/oracle/codemp/game/g_client.c:1888-2235`
pub fn ClientUserinfoChanged(ctx: GameContext<'_>, clientNum: c_int) {
    unsafe {
        let ent: *mut gentity_t = (*ctx.world).g_entities.as_mut_ptr().add(clientNum as usize);
        let client: *mut gclient_t = (*ent).client as *mut gclient_t;

        let mut teamTask: c_int = 0;
        let mut teamLeader: c_int = 0;
        let mut team: c_int = 0;
        let mut health: c_int = 0;

        let mut s: *mut c_char = core::ptr::null_mut();
        let mut model: [c_char; 260] = [0; 260];
        let mut forcePowers: [c_char; 260] = [0; 260];
        let mut oldname: [c_char; 1024] = [0; 1024];
        let mut c1: [c_char; 512] = [0; 512];
        let mut c2: [c_char; 512] = [0; 512];
        let mut userinfo: [c_char; 512] = [0; 512];
        let mut className: [c_char; 260] = [0; 260];
        let mut saberName: [c_char; 260] = [0; 260];
        let mut saber2Name: [c_char; 260] = [0; 260];
        let mut value: *mut c_char = core::ptr::null_mut();
        let mut maxHealth: c_int = 0;
        let mut modelChanged: qboolean = qfalse;

        trap::GetUserinfo(
            ctx.engine,
            mp_abi::game::syscalls::G_GET_USERINFO::GGetUserinfoArgs::new(
                clientNum,
                userinfo.as_mut_ptr(),
                512,
            ),
        );

        // check for malformed or illegal info strings
        if crate::q_shared::Info_Validate(userinfo.as_ptr()) == qfalse {
            write_cstr_field(&mut userinfo, "\\name\\badinfo");
        }

        // check for local client
        s = crate::q_shared::Info_ValueForKey(userinfo.as_ptr(), c"ip".as_ptr());
        if crate::q_shared::Q_stricmp(s, c"localhost".as_ptr()) == 0 {
            (*client).pers.localClient = qtrue;
        }

        // check the item prediction
        s = crate::q_shared::Info_ValueForKey(userinfo.as_ptr(), c"cg_predictItems".as_ptr());
        if crate::q_shared::cstr_to_int(s) == 0 {
            (*client).pers.predictItemPickup = qfalse;
        } else {
            (*client).pers.predictItemPickup = qtrue;
        }

        // set name
        crate::q_shared::Q_strncpyz(
            oldname.as_mut_ptr(),
            (*client).pers.netname.as_ptr(),
            1024,
        );
        s = crate::q_shared::Info_ValueForKey(userinfo.as_ptr(), c"name".as_ptr());
        ClientCleanName(ctx, s, (*client).pers.netname.as_mut_ptr(), 64);

        if (*client).sess.sessionTeam == TEAM_SPECTATOR {
            if (*client).sess.spectatorState == crate::client::spectator_state::spectatorState_t::SPECTATOR_SCOREBOARD {
                crate::q_shared::Q_strncpyz(
                    (*client).pers.netname.as_mut_ptr(),
                    c"scoreboard".as_ptr(),
                    64,
                );
            }
        }

        if (*client).pers.connected == CON_CONNECTED {
            if crate::q_shared::Q_strcmp(
                oldname.as_ptr(),
                (*client).pers.netname.as_ptr(),
            ) != 0
            {
                if (*client).pers.netnameTime > (*ctx.world).level.time {
                    let msg = format!(
                        "print \"{}\n\"",
                        cstr_to_str(G_GetStringEdString(
                            ctx,
                            cstr("MP_SVGAME").as_ptr() as *mut c_char,
                            cstr("NONAMECHANGE").as_ptr() as *mut c_char
                        ))
                    );
                    trap::SendServerCommand(
                        ctx.engine,
                        GSendServerCommandArgs::new(clientNum, cstr(&msg)),
                    );

                    crate::q_shared::Info_SetValueForKey(
                        userinfo.as_mut_ptr(),
                        c"name".as_ptr(),
                        oldname.as_ptr(),
                    );
                    trap::SetUserinfo(
                        ctx.engine,
                        mp_abi::game::syscalls::G_SET_USERINFO::GSetUserinfoArgs::new(
                            clientNum,
                            cstr(&cstr_to_str(userinfo.as_ptr())),
                        ),
                    );
                    write_cstr_field(&mut (*client).pers.netname, cstr_to_str(oldname.as_ptr()));
                } else {
                    let msg = format!(
                        "print \"{}{} {} {}\n\"",
                        cstr_to_str(oldname.as_ptr()),
                        S_COLOR_WHITE,
                        cstr_to_str(G_GetStringEdString(
                            ctx,
                            cstr("MP_SVGAME").as_ptr() as *mut c_char,
                            cstr("PLRENAME").as_ptr() as *mut c_char
                        )),
                        cstr_to_str((*client).pers.netname.as_ptr())
                    );
                    trap::SendServerCommand(
                        ctx.engine,
                        GSendServerCommandArgs::new(-1, cstr(&msg)),
                    );
                    (*client).pers.netnameTime = (*ctx.world).level.time + 5000;
                }
            }
        }

        // set model
        crate::q_shared::Q_strncpyz(
            model.as_mut_ptr(),
            crate::q_shared::Info_ValueForKey(userinfo.as_ptr(), c"model".as_ptr()),
            260,
        );

        if (*ctx.world).cvars.d_perPlayerGhoul2.integer != 0 {
            if crate::q_shared::Q_stricmp(model.as_ptr(), (*client).modelname.as_ptr()) != 0 {
                write_cstr_field(&mut (*client).modelname, cstr_to_str(model.as_ptr()));
                modelChanged = qtrue;
            }
        }

        // Get the skin RGB based on his userinfo
        value = crate::q_shared::Info_ValueForKey(userinfo.as_ptr(), c"char_color_red".as_ptr());
        if !value.is_null() && *value as c_int != 0 {
            (*client).ps.customRGBA[0] = crate::q_shared::cstr_to_int(value) as c_int;
        } else {
            (*client).ps.customRGBA[0] = 255;
        }

        value = crate::q_shared::Info_ValueForKey(userinfo.as_ptr(), c"char_color_green".as_ptr());
        if !value.is_null() && *value as c_int != 0 {
            (*client).ps.customRGBA[1] = crate::q_shared::cstr_to_int(value) as c_int;
        } else {
            (*client).ps.customRGBA[1] = 255;
        }

        value = crate::q_shared::Info_ValueForKey(userinfo.as_ptr(), c"char_color_blue".as_ptr());
        if !value.is_null() && *value as c_int != 0 {
            (*client).ps.customRGBA[2] = crate::q_shared::cstr_to_int(value) as c_int;
        } else {
            (*client).ps.customRGBA[2] = 255;
        }

        if ((*client).ps.customRGBA[0] + (*client).ps.customRGBA[1] + (*client).ps.customRGBA[2])
            < 100
        {
            // hmm, too dark!
            (*client).ps.customRGBA[0] = 255;
            (*client).ps.customRGBA[1] = 255;
            (*client).ps.customRGBA[2] = 255;
        }

        (*client).ps.customRGBA[3] = 255;

        crate::q_shared::Q_strncpyz(
            forcePowers.as_mut_ptr(),
            crate::q_shared::Info_ValueForKey(userinfo.as_ptr(), c"forcepowers".as_ptr()),
            260,
        );

        // bots set their team a few frames later
        if (*ctx.world).cvars.g_gametype.integer >= GT_TEAM
            && (*ctx.world).g_entities[clientNum as usize].r.svFlags & SVF_BOT != 0
        {
            s = crate::q_shared::Info_ValueForKey(userinfo.as_ptr(), c"team".as_ptr());
            if crate::q_shared::Q_stricmp(s, c"red".as_ptr()) == 0
                || crate::q_shared::Q_stricmp(s, c"r".as_ptr()) == 0
            {
                team = TEAM_RED;
            } else if crate::q_shared::Q_stricmp(s, c"blue".as_ptr()) == 0
                || crate::q_shared::Q_stricmp(s, c"b".as_ptr()) == 0
            {
                team = TEAM_BLUE;
            } else {
                // pick the team with the least number of players
                team = PickTeam(ctx, clientNum) as c_int;
            }
        } else {
            team = (*client).sess.sessionTeam;
        }

        // Set the siege class
        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE {
            write_cstr_field(&mut className, cstr_to_str((*client).sess.siegeClass.as_ptr()));

            // This function will see if the given class is legal for the given team.
            // If not className will be filled in with the first legal class for this team.
            // Now that the team is legal for sure, we'll go ahead and get an index for it.
            (*client).siegeClass =
                BG_SiegeFindClassIndexByName(className.as_ptr(), &(*ctx.world).bg_state);
            if (*client).siegeClass == -1 {
                // ok, get the first valid class for the team you're on then, I guess.
                BG_SiegeCheckClassLegality(team, className.as_mut_ptr(), &(*ctx.world).bg_state);
                write_cstr_field(&mut (*client).sess.siegeClass, cstr_to_str(className.as_ptr()));
                (*client).siegeClass =
                    BG_SiegeFindClassIndexByName(className.as_ptr(), &(*ctx.world).bg_state);
            } else {
                // otherwise, make sure the class we are using is legal.
                G_ValidateSiegeClassForTeam(ctx, ent, team);
                write_cstr_field(&mut className, cstr_to_str((*client).sess.siegeClass.as_ptr()));
            }

            // Set the sabers if the class dictates
            if (*client).siegeClass != -1 {
                let scl = &(*ctx.world).bg_state.bgSiegeClasses[(*client).siegeClass as usize];

                if scl.saber1[0] as c_int != 0 {
                    G_SetSaber(
                        ctx,
                        ent,
                        0,
                        scl.saber1.as_ptr() as *mut c_char,
                        qtrue,
                    );
                } else {
                    // default I guess
                    G_SetSaber(ctx, ent, 0, cstr("Kyle").as_ptr() as *mut c_char, qtrue);
                }
                if scl.saber2[0] as c_int != 0 {
                    G_SetSaber(
                        ctx,
                        ent,
                        1,
                        scl.saber2.as_ptr() as *mut c_char,
                        qtrue,
                    );
                } else {
                    // no second saber then
                    G_SetSaber(ctx, ent, 1, cstr("none").as_ptr() as *mut c_char, qtrue);
                }

                // make sure the saber models are updated
                G_SaberModelSetup(ctx, ent);

                if scl.forcedModel[0] as c_int != 0 {
                    // be sure to override the model we actually use
                    write_cstr_field(&mut model, cstr_to_str(scl.forcedModel.as_ptr()));
                    if (*ctx.world).cvars.d_perPlayerGhoul2.integer != 0 {
                        if crate::q_shared::Q_stricmp(model.as_ptr(), (*client).modelname.as_ptr())
                            != 0
                        {
                            write_cstr_field(&mut (*client).modelname, cstr_to_str(model.as_ptr()));
                            modelChanged = qtrue;
                        }
                    }
                }

                // force them to use their class model on the server, if the class dictates
                if G_PlayerHasCustomSkeleton(ent) != qfalse {
                    if crate::q_shared::Q_stricmp(model.as_ptr(), (*client).modelname.as_ptr())
                        != 0
                        || (*ent).localAnimIndex == 0
                    {
                        write_cstr_field(&mut (*client).modelname, cstr_to_str(model.as_ptr()));
                        modelChanged = qtrue;
                    }
                }
            }
        } else {
            write_cstr_field(&mut className, "none");
        }

        // Set the saber name
        write_cstr_field(&mut saberName, cstr_to_str((*client).sess.saberType.as_ptr()));
        write_cstr_field(&mut saber2Name, cstr_to_str((*client).sess.saber2Type.as_ptr()));

        // set max health
        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE && (*client).siegeClass != -1 {
            let scl = &(*ctx.world).bg_state.bgSiegeClasses[(*client).siegeClass as usize];
            maxHealth = 100;

            if scl.maxhealth != 0 {
                maxHealth = scl.maxhealth;
            }

            health = maxHealth;
        } else {
            maxHealth = 100;
            health = 100;
        }
        (*client).pers.maxHealth = health;
        if (*client).pers.maxHealth < 1 || (*client).pers.maxHealth > maxHealth {
            (*client).pers.maxHealth = 100;
        }
        (*client).ps.stats[STAT_MAX_HEALTH as usize] = (*client).pers.maxHealth;

        // send over a subset of the userinfo keys so other clients can
        // print scoreboards, display models, and play custom sounds
        let configstring_s = if (*ent).r.svFlags & SVF_BOT != 0 {
            format!(
                "n\\{}\\t\\{}\\model\\{}\\c1\\{}\\c2\\{}\\hc\\{}\\w\\{}\\l\\{}\\skill\\{}\\tt\\{}\\tl\\{}\\siegeclass\\{}\\st\\{}\\st2\\{}\\dt\\{}\\sdt\\{}",
                cstr_to_str((*client).pers.netname.as_ptr()),
                team,
                cstr_to_str(model.as_ptr()),
                cstr_to_str(c1.as_ptr()),
                cstr_to_str(c2.as_ptr()),
                (*client).pers.maxHealth,
                (*client).sess.wins,
                (*client).sess.losses,
                cstr_to_str(crate::q_shared::Info_ValueForKey(userinfo.as_ptr(), c"skill".as_ptr())),
                teamTask,
                teamLeader,
                cstr_to_str(className.as_ptr()),
                cstr_to_str(saberName.as_ptr()),
                cstr_to_str(saber2Name.as_ptr()),
                (*client).sess.duelTeam,
                (*client).sess.siegeDesiredTeam
            )
        } else if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE {
            // more crap to send
            format!(
                "n\\{}\\t\\{}\\model\\{}\\c1\\{}\\c2\\{}\\hc\\{}\\w\\{}\\l\\{}\\tt\\{}\\tl\\{}\\siegeclass\\{}\\st\\{}\\st2\\{}\\dt\\{}\\sdt\\{}",
                cstr_to_str((*client).pers.netname.as_ptr()),
                (*client).sess.sessionTeam,
                cstr_to_str(model.as_ptr()),
                cstr_to_str(c1.as_ptr()),
                cstr_to_str(c2.as_ptr()),
                (*client).pers.maxHealth,
                (*client).sess.wins,
                (*client).sess.losses,
                teamTask,
                teamLeader,
                cstr_to_str(className.as_ptr()),
                cstr_to_str(saberName.as_ptr()),
                cstr_to_str(saber2Name.as_ptr()),
                (*client).sess.duelTeam,
                (*client).sess.siegeDesiredTeam
            )
        } else {
            format!(
                "n\\{}\\t\\{}\\model\\{}\\c1\\{}\\c2\\{}\\hc\\{}\\w\\{}\\l\\{}\\tt\\{}\\tl\\{}\\st\\{}\\st2\\{}\\dt\\{}",
                cstr_to_str((*client).pers.netname.as_ptr()),
                (*client).sess.sessionTeam,
                cstr_to_str(model.as_ptr()),
                cstr_to_str(c1.as_ptr()),
                cstr_to_str(c2.as_ptr()),
                (*client).pers.maxHealth,
                (*client).sess.wins,
                (*client).sess.losses,
                teamTask,
                teamLeader,
                cstr_to_str(saberName.as_ptr()),
                cstr_to_str(saber2Name.as_ptr()),
                (*client).sess.duelTeam
            )
        };

        trap::SetConfigstring(
            ctx.engine,
            GSetConfigstringArgs::new(CS_PLAYERS + clientNum, cstr(&configstring_s)),
        );

        if modelChanged != qfalse {
            // only going to be true for allowable server-side custom skeleton cases
            // update the server g2 instance if appropriate
            let modelname_ptr =
                crate::q_shared::Info_ValueForKey(userinfo.as_ptr(), c"model".as_ptr());
            SetupGameGhoul2Model(ctx, ent, modelname_ptr, core::ptr::null_mut());

            if !(*ent).ghoul2.is_null() && !(*ent).client.is_null() {
                (*((*ent).client as *mut gclient_t)).renderInfo.lastG2 = core::ptr::null_mut();
                // update the renderinfo bolts next update.
            }

            (*client).torsoAnimExecute = -1;
            (*client).legsAnimExecute = -1;
            (*client).torsoLastFlip = qfalse;
            (*client).legsLastFlip = qfalse;
        }

        if (*ctx.world).cvars.g_logClientInfo.integer != 0 {
            G_LogPrintf(
                ctx,
                cstr(&format!("ClientUserinfoChanged: {} {}\n", clientNum, cstr_to_str(configstring_s.as_ptr() as *const c_char))).as_ptr(),
            );
        }
    }
}

/// Raven `SetClientViewAngle`. No `level`/cvar/trap access, so no `GameContext`
/// (unlike most of this file's spine).
///
/// Source: `oracle/oracle/codemp/game/g_client.c:1109-1125`
pub fn SetClientViewAngle(ent: *mut gentity_t, angle: vec3_t) {
    unsafe {
        // Raven `ANGLE2SHORT(x)` == `((int)((x)*65536/360) & 65535)`.
        for i in 0..3 {
            let cmd_angle = ((angle[i] * 65536.0 / 360.0) as c_int) & 65535;
            (*((*ent).client as *mut gclient_t)).ps.delta_angles[i] =
                cmd_angle - (*((*ent).client as *mut gclient_t)).pers.cmd.angles[i] as c_int;
        }
        (*ent).s.angles = angle;
        (*((*ent).client as *mut gclient_t)).ps.viewangles = (*ent).s.angles;
    }
}
